-- Bổ sung thông tin cây (08/10/2026, chủ shop nhờ "lấy thông tin trên mạng bổ sung các thông tin còn thiếu, trừ ảnh") cho 217 cây nạp ở 0034–0036:
-- mô tả ngắn, bộ thông số (ánh sáng, tưới nước, đất, bón phân, nhiệt độ, mức độ dễ chăm, tốc độ lớn, kích thước trưởng thành, an toàn thú cưng,
-- công dụng, nhân giống, nguồn gốc, tên khoa học, sâu bệnh, phù hợp với ai), tên gọi khác (tìm kiếm), phong thủy (ý nghĩa dân gian + mệnh theo màu lá/hoa),
-- đặc điểm cho bộ lọc / tư vấn chọn cây (màu, ánh sáng, độ dễ chăm, an toàn thú cưng, chịu gió). Tên khoa học và an toàn thú cưng chỉ ghi khi chắc chắn.
-- Chỉ ghi đè phần admin chưa sửa: thông số khi sản phẩm mới chỉ có dòng "Chiều cao"; mô tả khi còn đúng câu tự sinh; tên gọi khác khi trống;
-- phong thủy khi chưa có; đặc điểm chỉ điền mục đang trống.
-- Tách "Chuỗi ngọc": file Excel gộp 2 cây khác nhau cùng tên — cây bụi Duranta (ban công / sân vườn / công trình) và sen đá dây (để bàn)
-- → giữ "Chuỗi ngọc" là cây bụi, thêm sản phẩm mới "Sen đá chuỗi ngọc" (chỉ khi chưa có đơn / chưa ai sửa).
CREATE TEMP TABLE "_m37" ("slug" text PRIMARY KEY, "specs" jsonb, "attrs" jsonb, "fs" jsonb, "kw" jsonb, "old_lead" text, "lead" text);--> statement-breakpoint
UPDATE "products" p SET "specs" = m.specs FROM "_m37" m
WHERE p.slug = m.slug AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p.specs) e WHERE e->>0 <> 'Chiều cao');--> statement-breakpoint
UPDATE "products" p SET "lead" = m.lead FROM "_m37" m WHERE p.slug = m.slug AND p.lead = m.old_lead;--> statement-breakpoint
UPDATE "products" p SET "keywords" = m.kw FROM "_m37" m WHERE p.slug = m.slug AND p.keywords = '[]'::jsonb;--> statement-breakpoint
UPDATE "products" p SET "fengshui" = m.fs FROM "_m37" m WHERE p.slug = m.slug AND p.fengshui IS NULL AND m.fs IS NOT NULL;--> statement-breakpoint
UPDATE "products" p SET "attrs" = m.attrs || coalesce((
  SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(p.attrs) e
  WHERE e.value NOT IN ('[]'::jsonb, 'null'::jsonb, '""'::jsonb, 'false'::jsonb)
), '{}'::jsonb)
FROM "_m37" m WHERE p.slug = m.slug;--> statement-breakpoint
DROP TABLE "_m37";--> statement-breakpoint
DO $$
DECLARE ok boolean; st int; base int; r record;
BEGIN
  SELECT coalesce((SELECT jsonb_agg(label ORDER BY idx) FROM "product_options" WHERE product_slug = 'chuoi-ngoc') = '["Dây dài 20–30cm", "Cao 30–50cm", "Cao 50–80cm", "Cao 80–150cm"]'::jsonb, false)
     AND NOT EXISTS (SELECT 1 FROM "order_items" WHERE product_slug = 'chuoi-ngoc')
     AND NOT EXISTS (SELECT 1 FROM "stock_moves" WHERE product_slug = 'chuoi-ngoc' AND (actor <> 'Hệ thống' OR reason <> 'import'))
     AND NOT EXISTS (SELECT 1 FROM "products" WHERE slug = 'sen-da-chuoi-ngoc' OR lower(name) = 'sen đá chuỗi ngọc')
     AND EXISTS (SELECT 1 FROM "subcategories" WHERE category_slug = 'cay-canh' AND slug = 'cay-san-vuon')
    INTO ok;
  IF NOT ok THEN RETURN; END IF;
  SELECT id INTO st FROM "stores" ORDER BY is_default DESC, id LIMIT 1;
  DELETE FROM "stock_moves" WHERE product_slug = 'chuoi-ngoc';
  DELETE FROM "stock_lots" WHERE product_slug = 'chuoi-ngoc';
  DELETE FROM "product_options" WHERE product_slug = 'chuoi-ngoc';
  UPDATE "products" SET "sub" = 'cay-san-vuon',
    "extra_subs" = (SELECT coalesce(jsonb_agg(s), '[]'::jsonb) FROM unnest(ARRAY['cay-ban-cong', 'cay-cong-trinh']) s
                    WHERE EXISTS (SELECT 1 FROM "subcategories" WHERE category_slug = 'cay-canh' AND slug = s)),
    "spec" = 'Ban công · Sân vườn · Công trình',
    "attrs" = jsonb_set(coalesce("attrs", '{}'::jsonb), '{viTri}', '["ban-cong", "ngoai-troi"]'::jsonb)
  WHERE slug = 'chuoi-ngoc';
  SELECT greatest(90000, coalesce(max(substring(sku FROM '^MT-(\d+)$')::int), 0)) INTO base FROM "products" WHERE sku ~ '^MT-\d+$';
  VALUES ('sen-da-chuoi-ngoc', 'MT-' || (base + 1), 'Sen đá chuỗi ngọc', 'cay-canh', 'cay-de-ban',
    (SELECT coalesce(jsonb_agg(s), '[]'::jsonb) FROM unnest(ARRAY['cay-ban-cong']) s WHERE EXISTS (SELECT 1 FROM "subcategories" WHERE category_slug = 'cay-canh' AND slug = s)),
    'cactus', 'Việt Nam', 'plant', 'Cây', 'Để bàn · Ban công', 'Sen đá chuỗi ngọc là cây mọng nước dạng dây, lá tròn như những hạt ngọc xâu chuỗi rủ xuống. Cây hợp chậu treo cửa sổ, kệ cao có nắng sáng, cần tưới rất ít.', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Dây rủ dài 30–60cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Curio rowleyanus (syn. Senecio rowleyanus)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "doc", "viTri": ["van-phong", "treo"], "kichThuoc": "mini"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tình bạn, tình yêu bền vững", "placement": "Bàn làm việc gần cửa sổ, ban công"}'::jsonb, '["Chuỗi ngọc", "String of pearls"]'::jsonb, true);
  IF st IS NOT NULL THEN
    FOR r IN SELECT product_slug, idx FROM "product_options" WHERE product_slug IN ('chuoi-ngoc', 'sen-da-chuoi-ngoc') AND price > 0 LOOP
      WITH lot AS (
      )
      SELECT r.product_slug, r.idx, st, lot.id, 10, 10, 'import', 'Tồn đầu kỳ', 'Hệ thống' FROM lot;
      UPDATE "product_options" SET "stock" = 10 WHERE product_slug = r.product_slug AND idx = r.idx;
    END LOOP;
  END IF;
END $$;
