INSERT INTO "_m37" VALUES
('kim-tien', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn văn phòng tốt"], ["Tưới nước", "Tưới khi đất khô gần hết, khoảng 1 lần/tuần; củ trữ nước nên rất chịu hạn"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–60cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 60–100cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí văn phòng, phòng khách; quà khai trương, tân gia"], ["Cách nhân giống", "Giâm lá, tách củ"], ["Nguồn gốc", "Đông Phi"], ["Tên khoa học", "Zamioculcas zamiifolia"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người bận rộn, mới trồng cây, văn phòng ít nắng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tiền tài, phú quý; lá mọc thẳng như cành tiền tài lộc", "placement": "Bàn làm việc, quầy thu ngân, góc Đông Nam phòng khách"}'::jsonb, '["Kim phát tài", "ZZ plant"]'::jsonb, 'Kim tiền thuộc nhóm cây văn phòng, cây trong nhà, cây ban công. Quy cách: Cao 50–60cm.', 'Kim tiền có lá kép xanh đậm bóng mọc thẳng, gốc là củ trữ nước nên rất chịu hạn và sống khỏe trong phòng máy lạnh. Đây là loại cây được chọn nhiều làm quà khai trương, đặt bàn làm việc hoặc phòng khách.'),
('luoi-ho', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ; chịu bóng râm, đèn văn phòng"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; lá mọng nước, rất chịu hạn"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 50–120cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất, đặt phòng ngủ, văn phòng, lối vào"], ["Cách nhân giống", "Tách bụi, giâm lá"], ["Nguồn gốc", "Tây Phi nhiệt đới"], ["Tên khoa học", "Dracaena trifasciata (syn. Sansevieria trifasciata)"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, hay đi công tác, ít thời gian"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "den", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Lá nhọn mọc thẳng tượng trưng cho sự mạnh mẽ, được tin là giúp xua điều xấu, bảo vệ gia chủ", "placement": "Lối vào, góc phòng khách, bàn làm việc"}'::jsonb, '["Hổ vĩ", "Snake plant", "Sansevieria"]'::jsonb, 'Lưỡi hổ thuộc nhóm cây văn phòng, cây trong nhà, cây ban công. Có 2 quy cách.', 'Lưỡi hổ có lá dày, mọc thẳng đứng, vằn xanh đậm xen xanh nhạt. Cây gần như không cần chăm, chịu hạn và thiếu sáng tốt, thường được đặt trong phòng ngủ, văn phòng.'),
('trau-ba', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn điện"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–3m khi leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột, chậu treo, để kệ, thủy sinh"], ["Cách nhân giống", "Giâm ngọn vào nước hoặc đất, rất dễ ra rễ"], ["Nguồn gốc", "Quần đảo Society (Thái Bình Dương)"], ["Tên khoa học", "Epipremnum aureum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, căn hộ, văn phòng"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự phát triển, may mắn, tiền tài", "placement": "Kệ sách, bàn làm việc, góc phòng khách"}'::jsonb, '["Vạn niên thanh leo", "Pothos", "Hoàng tâm"]'::jsonb, 'Trầu bà thuộc nhóm cây văn phòng. Có 2 quy cách.', 'Trầu bà là cây dây leo lá hình tim, xanh bóng, lớn nhanh, có thể leo cột, rủ chậu treo hoặc trồng trong nước. Cây sống khỏe trong phòng ít sáng, rất hợp người mới trồng cây.'),
('trau-ba-de-vuong', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50–100cm, tán rộng"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí sảnh, phòng khách, văn phòng; quà tặng"], ["Cách nhân giống", "Tách chồi con"], ["Nguồn gốc", "Nam Mỹ (giống lai)"], ["Tên khoa học", "Philodendron ''Imperial''"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Văn phòng, gia đình muốn cây lá to sang trọng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi và dáng lá uy nghi tượng trưng cho quyền lực, thịnh vượng, thăng tiến", "placement": "Phòng khách, phòng giám đốc, sảnh"}'::jsonb, '["Đế vương", "Philodendron Imperial"]'::jsonb, 'Trầu bà đế vương thuộc nhóm cây văn phòng, cây để bàn. Có 2 quy cách.', 'Trầu bà đế vương có lá to bản, dày, bóng, mọc xòe từ gốc tạo dáng bề thế. Cây chịu bóng tốt, có thể trồng đất hoặc thủy sinh, hợp đặt sảnh, phòng khách.'),
('phat-tai', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh; quà khai trương"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng muốn cây cao dễ chăm"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa phát tài phát lộc, làm ăn thuận lợi", "placement": "Phòng khách, phòng làm việc, góc Đông Nam"}'::jsonb, '["Thiết mộc lan", "Corn plant"]'::jsonb, 'Phát tài thuộc nhóm cây văn phòng, cây ban công. Có 2 quy cách.', 'Phát tài có thân gỗ thẳng, lá dài xanh bóng mọc thành chùm ở ngọn; cây trưởng thành có thể ra hoa trắng thơm về đêm. Cây chịu bóng, ít sâu bệnh, hợp đặt phòng khách, văn phòng.'),
('van-nien-thanh', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 40cm–1m"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Trung và Nam Mỹ"], ["Tên khoa học", "Dieffenbachia spp"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa xanh tươi muôn năm, sức khỏe, trường thọ", "placement": "Phòng khách, góc Đông"}'::jsonb, '["Môn trường sinh", "Dumb cane"]'::jsonb, 'Vạn niên thanh thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–60cm.', 'Vạn niên thanh có lá to bản xanh đậm điểm mảng trắng kem, thân mập mọng nước. Cây chịu bóng, lớn khỏe, hợp đặt phòng khách, văn phòng. Nhựa cây gây ngứa nên để xa tầm tay trẻ nhỏ.'),
('cau-tieu-tram', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 30cm–1m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn, kệ, góc phòng nhỏ; ghép tiểu cảnh"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Mexico, Guatemala"], ["Tên khoa học", "Chamaedorea elegans"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Văn phòng, gia đình có trẻ nhỏ, thú cưng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sinh sôi, may mắn, gia đình sum vầy", "placement": "Bàn làm việc, phòng khách"}'::jsonb, '["Cau tiểu châm", "Parlor palm"]'::jsonb, 'Cau tiểu trâm thuộc nhóm cây văn phòng, cây để bàn, cây ban công. Có 3 quy cách.', 'Cau tiểu trâm là loài cau nhỏ, lá kép mềm mại, mọc thành bụi, rất chịu bóng nên sống tốt trong nhà. Cây giúp góc làm việc tươi mát, an toàn với thú cưng.'),
('ngu-gia-bi', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, ban công, sân vườn; trồng viền"], ["Cách nhân giống", "Giâm cành"], ["Nguồn gốc", "Đài Loan, Hải Nam (Trung Quốc)"], ["Tên khoa học", "Heptapleurum arboricola (syn. Schefflera arboricola)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá xòe như bàn tay tượng trưng cho sự đoàn kết, che chở, gia đình hòa thuận", "placement": "Phòng khách, ban công, góc Đông"}'::jsonb, '["Chân chim", "Schefflera"]'::jsonb, 'Ngũ gia bì thuộc nhóm cây văn phòng, cây trong nhà, cây ban công, cây sân vườn. Có 3 quy cách.', 'Ngũ gia bì có lá kép xòe như bàn tay với 5–8 lá chét bóng, cây phân cành nhiều, dễ tạo tán. Cây vừa đặt trong nhà sáng, vừa trồng ban công, sân vườn, và được tin là giúp đuổi muỗi.'),
('duoi-cong', '[["Ánh sáng", "Ánh sáng tán xạ nhẹ; nắng trực tiếp làm bạc, cháy lá"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần; dùng nước để lắng qua đêm"], ["Đất trồng", "Đất giàu mùn, tơi xốp, giữ ẩm nhưng thoát nước tốt"], ["Bón phân", "NPK cân đối pha loãng, 1 lần/tháng trong mùa sinh trưởng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–30°C, ưa ẩm cao; phun sương khi không khí khô"], ["Mức độ dễ chăm", "Trung bình — cần giữ ẩm đều"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn, kệ, góc phòng mát"], ["Cách nhân giống", "Tách bụi khi thay chậu"], ["Nguồn gốc", "Đông Brazil"], ["Tên khoa học", "Goeppertia makoyana (syn. Calathea makoyana)"], ["Sâu bệnh thường gặp", "Cháy mép lá khi không khí khô, nhện đỏ, rệp sáp"], ["Phù hợp với ai", "Người thích cây lá hoa văn, nhà có thú cưng"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["sang", "ram"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sung túc, may mắn", "placement": "Phòng khách, phòng làm việc"}'::jsonb, '["Calathea", "Peacock plant"]'::jsonb, 'Đuôi công thuộc nhóm cây văn phòng. Có 2 quy cách.', 'Đuôi công có lá hoa văn như lông đuôi công, mặt dưới ánh tím, lá khép lại vào ban đêm. Cây ưa bóng mát, độ ẩm cao, an toàn với thú cưng.'),
('phu-quy', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, kệ, phòng khách; quà khai trương, tân gia"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Nam Á (giống lai)"], ["Tên khoa học", "Aglaonema (giống lai lá đỏ)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["do-hong", "loang"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tên gọi và sắc đỏ tượng trưng cho phú quý, giàu sang, may mắn", "placement": "Bàn làm việc, phòng khách, quầy lễ tân"}'::jsonb, '["Aglaonema", "Valentine"]'::jsonb, 'Phú quý thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà. Có 3 quy cách.', 'Phú quý có lá xanh viền và gân hồng đỏ, mọc thành bụi gọn. Cây chịu bóng, dễ chăm, trồng đất hoặc thủy sinh đều được, thường làm quà tặng.'),
('hong-mon', '[["Ánh sáng", "Ánh sáng tán xạ sáng; thiếu sáng ít ra hoa"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, phòng khách, quà tặng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Colombia, Ecuador"], ["Tên khoa học", "Anthurium andraeanum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích cây có hoa trong nhà"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ tượng trưng cho tình yêu, may mắn, gia đình đầm ấm", "placement": "Phòng khách, bàn làm việc"}'::jsonb, '["Vĩ hoa tròn", "Anthurium"]'::jsonb, 'Hồng môn thuộc nhóm cây văn phòng, cây trong nhà. Có 2 quy cách.', 'Hồng môn có hoa mo đỏ bóng hình trái tim, nhụy vàng, bền hoa hàng tuần và ra hoa quanh năm khi đủ sáng. Cây hợp đặt bàn, kệ, phòng khách.'),
('sen-da', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–20cm"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Mexico, Trung Mỹ, Nam Phi (tùy loài)"], ["Tên khoa học", "Echeveria và các chi họ Thuốc bỏng (Crassulaceae)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tình bạn, tình yêu bền vững", "placement": "Bàn làm việc gần cửa sổ, ban công"}'::jsonb, '["Succulent"]'::jsonb, 'Sen đá thuộc nhóm cây văn phòng, cây ban công. Có 2 quy cách.', 'Sen đá có lá mọng nước xếp thành hình hoa thị, nhiều màu xanh, hồng, tím tùy giống. Cây nhỏ xinh, chịu hạn, chỉ cần đủ nắng, hợp để bàn sáng, ban công.'),
('xuong-rong-mini', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ/ngày"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; mùa mưa hạn chế tưới"], ["Đất trồng", "Giá thể cát, sỏi nhỏ, trấu hun, rất thoát nước"], ["Bón phân", "Phân tan chậm liều nhẹ 2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–38°C, chịu nóng tốt, kỵ ẩm ướt kéo dài"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–15cm"], ["Công dụng", "Để bàn sáng, cửa sổ, quà tặng"], ["Cách nhân giống", "Tách chồi con, giâm nhánh"], ["Nguồn gốc", "Châu Mỹ"], ["Tên khoa học", "Họ Xương rồng (Cactaceae)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Được tin là giúp hóa giải điều xấu, bảo vệ", "placement": "Cửa sổ, ban công"}'::jsonb, '["Cactus"]'::jsonb, 'Xương rồng mini thuộc nhóm cây văn phòng. Quy cách: Cỡ mini.', 'Xương rồng mini gồm nhiều giống xương rồng nhỏ xinh trồng chậu để bàn. Cây gần như không cần chăm, chỉ cần nắng và rất ít nước.'),
('ngoc-ngan', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 20–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, kệ, phòng khách; quà tặng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Aglaonema (giống lá đốm trắng)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["bac-trang", "xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho tình yêu bền chặt, may mắn, bình an", "placement": "Bàn làm việc, phòng khách, phòng ngủ"}'::jsonb, '["Valentine", "Aglaonema Snow White"]'::jsonb, 'Ngọc ngân thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà. Có 2 quy cách.', 'Ngọc ngân có lá thuôn dài, phần giữa lá trắng bạc, viền xanh, nhìn thanh thoát. Cây chịu bóng, dễ chăm, trồng đất hoặc thủy sinh, hợp để bàn, kệ.'),
('duong-xi', '[["Ánh sáng", "Ánh sáng tán xạ, bóng râm; tránh nắng gắt"], ["Tưới nước", "Giữ đất luôn ẩm, tưới 1 lần/ngày mùa khô; phun sương lên lá"], ["Đất trồng", "Đất giàu mùn, xơ dừa, giữ ẩm tốt"], ["Bón phân", "Phân hữu cơ hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–30°C, ưa ẩm cao"], ["Mức độ dễ chăm", "Trung bình — không để khô đất"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 30–60cm, lá rủ dài"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Giỏ treo, chậu treo hiên, ban công, kệ cao"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Vùng nhiệt đới châu Mỹ"], ["Tên khoa học", "Nephrolepis exaltata"], ["Sâu bệnh thường gặp", "Khô, rụng lá khi thiếu ẩm; rệp sáp"], ["Phù hợp với ai", "Ban công, hiên có bóng mát"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bình yên, che chở", "placement": "Hiên nhà, ban công, cửa sổ"}'::jsonb, '["Dương xỉ lá kiếm", "Boston fern"]'::jsonb, 'Dương xỉ thuộc nhóm cây văn phòng, cây trong nhà, cây ban công, cây sân vườn. Có 3 quy cách.', 'Dương xỉ có lá kép dài mềm mại rủ xuống, xanh mướt, rất hợp chậu treo, giỏ treo. Cây ưa bóng mát, ẩm, giúp ban công, hiên nhà mát mắt.'),
('phat-loc', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Trồng nước thì thay nước 7–10 ngày/lần; trồng đất tưới khi mặt đất se khô"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 20–60cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Để bàn, kệ, bàn thờ thần tài, quà tặng"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Trung Phi"], ["Tên khoa học", "Dracaena sanderiana"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho phát tài phát lộc; số tầng, số cây mang ý nghĩa chúc phúc khác nhau", "placement": "Quầy thu ngân, bàn làm việc, bàn thờ thần tài"}'::jsonb, '["Trúc phát lộc", "Lucky bamboo"]'::jsonb, 'Phát lộc thuộc nhóm cây văn phòng, cây để bàn. Có 2 quy cách.', 'Phát lộc là cây trúc may mắn thân xanh chia đốt, thường được bó thành tháp 2–3 tầng hoặc uốn xoắn. Cây sống được trong nước hoặc đất, rất dễ chăm, hợp đặt bàn, quầy, bàn thờ thần tài.'),
('tung-bong-lai', '[["Ánh sáng", "Nắng nhẹ, nên phơi nắng 2–3 giờ/ngày nếu để trong nhà"], ["Tưới nước", "Tưới 1–2 lần/tuần, tránh úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–50cm, tán xòe như mây"], ["Công dụng", "Bonsai để bàn, kệ sáng, quà tặng"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nhật Bản"], ["Tên khoa học", "Juniperus procumbens ''Nana''"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người thích bonsai mini"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "sang"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho thịnh vượng, trường thọ, may mắn", "placement": "Bàn làm việc gần cửa sổ, phòng khách sáng"}'::jsonb, '["Tùng Nhật", "Japanese garden juniper"]'::jsonb, 'Tùng bồng lai thuộc nhóm cây văn phòng, cây sân vườn. Có 2 quy cách.', 'Tùng bồng lai có lá kim nhỏ mọc dày thành từng tầng tán như đám mây, dáng bonsai mini rất đẹp. Cây hợp để bàn sáng, cửa sổ, cần phơi nắng định kỳ.'),
('lan-quan-tu', '[["Ánh sáng", "Ánh sáng tán xạ, tránh nắng gắt"], ["Tưới nước", "Tưới khi đất se khô, 1–2 lần/tuần; rễ mập dễ thối nếu úng"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 40–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Phòng khách, sảnh, quà tặng"], ["Cách nhân giống", "Tách cây con, gieo hạt"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Clivia miniata"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích cây hoa lâu năm"]]'::jsonb, '{"mau": ["xanh-dam", "co-hoa"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho người quân tử ngay thẳng, cao quý; hoa cam mang ý nghĩa may mắn", "placement": "Phòng khách, phòng làm việc"}'::jsonb, '["Quân tử lan", "Bush lily"]'::jsonb, 'Lan quân tử thuộc nhóm cây văn phòng. Quy cách: 15–20 lá.', 'Lan quân tử có lá dài dày xanh đậm xếp đối xứng hai hàng, khi ra hoa cho chùm hoa hình phễu màu cam rực rỡ. Cây chịu bóng, sống lâu năm, hợp phòng khách.'),
('van-loc', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, kệ, phòng khách; quà tặng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Nam Á (giống lai)"], ["Tên khoa học", "Aglaonema (giống lai, nhóm Rotundum)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["do-hong", "xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tên gọi mang ý nghĩa vạn sự may mắn, tài lộc dồi dào", "placement": "Phòng khách, bàn làm việc, quầy thu ngân"}'::jsonb, '["Thiên phú", "Aglaonema"]'::jsonb, 'Vạn lộc thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà. Có 3 quy cách.', 'Vạn lộc có lá hồng đỏ xen xanh, gân lá nổi rõ, mọc thành bụi tròn đẹp. Cây chịu bóng, dễ chăm, là cây phong thủy được chọn nhiều để tặng dịp khai trương, Tết.'),
('truong-sinh', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng khá"], ["Tưới nước", "Tưới khi đất khô gần hết, 1 lần/tuần; lá dày trữ nước"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–30cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn, kệ, quà tặng"], ["Cách nhân giống", "Giâm lá, giâm ngọn"], ["Nguồn gốc", "Florida (Mỹ), Mexico, vùng Caribe"], ["Tên khoa học", "Peperomia obtusifolia"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Văn phòng, người bận rộn, nhà có thú cưng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa sống lâu, sức khỏe bền vững", "placement": "Bàn làm việc, kệ"}'::jsonb, '["Baby rubber plant", "Peperomia"]'::jsonb, 'Trường sinh thuộc nhóm cây văn phòng. Quy cách: Cao 20–30cm.', 'Trường sinh có lá dày tròn xanh bóng mọc so le, dáng gọn nhỏ xinh. Cây chịu bóng, ít phải tưới, hợp để bàn làm việc, kệ sách.'),
('hoa-giay', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ, càng nắng càng nhiều hoa"], ["Tưới nước", "Tưới khi đất khô; hơi hạn mới ra nhiều hoa, kỵ úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m, có thể leo giàn"], ["An toàn thú cưng", "Thân có gai, nhựa có thể gây kích ứng nhẹ"], ["Công dụng", "Leo cổng, giàn, ban công, bonsai, hàng rào"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Bougainvillea"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Nhà có sân, ban công nhiều nắng"]]'::jsonb, '{"mau": ["do-hong", "tim", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu bền bỉ, sự may mắn, hưng thịnh", "placement": "Cổng, ban công, sân trước"}'::jsonb, '["Bông giấy", "Bougainvillea"]'::jsonb, 'Hoa giấy thuộc nhóm cây sân vườn, cây ban công. Có 2 quy cách.', 'Hoa giấy có lá bắc mỏng như giấy nhiều màu hồng, tím, đỏ, trắng, nở rộ khi đủ nắng. Cây chịu nắng nóng, chịu hạn, dễ tạo dáng bonsai hoặc leo giàn, cổng.'),
('loc-vung', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–10m tùy dáng (bonsai hoặc bóng mát)"], ["Công dụng", "Sân vườn, cây bóng mát, cây dáng thế, chưng Tết"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á, Bắc Úc"], ["Tên khoa học", "Barringtonia acutangula"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, nhà có sân, công trình"]]'::jsonb, '{"mau": ["xanh", "do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên \"lộc\" mang ý nghĩa tài lộc, may mắn; chuỗi hoa đỏ tượng trưng cho sung túc", "placement": "Sân trước, cạnh hồ nước"}'::jsonb, '["Chiếc"]'::jsonb, 'Lộc vừng thuộc nhóm cây sân vườn, cây công trình. Có 4 quy cách.', 'Lộc vừng có lá non đỏ hồng, chuỗi hoa đỏ dài rủ xuống thướt tha khi nở. Cây trồng làm cây bóng mát, cây dáng thế sân vườn, được ưa chuộng chưng Tết.'),
('kim-quyt', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "0,8–1m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Chưng Tết, cây dáng thế, sân vườn"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Triphasia trifolia"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Gia đình, người chơi cây cảnh"]]'::jsonb, '{"mau": ["xanh-dam", "do-hong"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Trái đỏ sai quả tượng trưng cho may mắn, sung túc", "placement": "Phòng khách dịp Tết, sân trước"}'::jsonb, '["Kim quất", "Limeberry"]'::jsonb, 'Kim quýt thuộc nhóm cây sân vườn. Quy cách: Cao 0,8–1m.', 'Kim quýt là cây bụi lá nhỏ có gai, hoa trắng thơm, trái nhỏ tròn đỏ tươi sai chùm. Cây dễ tạo dáng, thường chưng Tết hoặc trồng chậu sân vườn.'),
('dam-but', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "0,8–1m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Hàng rào, sân vườn, bồn hoa"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Á"], ["Tên khoa học", "Hibiscus rosa-sinensis"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Nhà có sân, công trình"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "an-toan", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa đỏ tượng trưng cho sự nhiệt huyết, may mắn", "placement": "Sân trước, hàng rào"}'::jsonb, '["Râm bụt", "Bông bụp", "Hibiscus"]'::jsonb, 'Dâm bụt thuộc nhóm cây sân vườn. Quy cách: Bầu, cao 0,8–1m.', 'Dâm bụt có hoa to 5 cánh màu đỏ, hồng, vàng với nhụy dài, nở quanh năm. Cây chịu nắng, lớn nhanh, dễ trồng làm hàng rào, bồn hoa.'),
('hoa-muoi-gio', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; lá mọng nên chịu hạn tốt"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–20cm, bò lan"], ["An toàn thú cưng", "Không — độc với mèo"], ["Công dụng", "Chậu ban công, bồn viền, chậu treo"], ["Cách nhân giống", "Giâm cành, rất dễ ra rễ"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Portulaca grandiflora"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nhiều nắng, người mới trồng hoa"]]'::jsonb, '{"mau": ["do-hong", "vang", "tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự tươi vui, may mắn", "placement": "Ban công, sân thượng"}'::jsonb, '["Moss rose"]'::jsonb, 'Hoa mười giờ thuộc nhóm cây sân vườn. Quy cách: Bầu 10cm.', 'Mười giờ là cây thân thảo mọng nước, hoa nhiều màu nở rộ vào buổi sáng nắng. Cây cực kỳ dễ trồng, chịu nắng nóng, hợp chậu ban công, bồn viền.'),
('cam-tu-mai', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "15–20cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 20–50cm, tán gọn"], ["Công dụng", "Trồng thảm, viền bồn, tiểu cảnh"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Mexico, Trung Mỹ"], ["Tên khoa học", "Cuphea hyssopifolia"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Sân vườn, công trình cảnh quan"]]'::jsonb, '{"mau": ["tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa tím tượng trưng cho sự thủy chung, bình yên", "placement": "Bồn hoa sân trước"}'::jsonb, '["False heather"]'::jsonb, 'Cẩm tú mai thuộc nhóm cây sân vườn. Quy cách: Bầu 10cm, cao 15–20cm.', 'Cẩm tú mai là cây bụi thấp lá nhỏ li ti, hoa tím nhỏ nở quanh năm. Cây chịu nắng, dễ cắt tỉa, chủ yếu trồng thảm, viền bồn hoa, tiểu cảnh.'),
('ngoc-but', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "0,6–0,8m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–2m"], ["Công dụng", "Hàng rào, sân vườn, chậu lớn"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Tabernaemontana divaricata"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Nhà có sân"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng tượng trưng cho sự thanh khiết, học hành thuận lợi (tên \"ngọc bút\")", "placement": "Sân trước, sân vườn"}'::jsonb, '["Lài trâu", "Bánh hỏi"]'::jsonb, 'Ngọc bút thuộc nhóm cây sân vườn. Quy cách: Bầu, cao 0,6–0,8m.', 'Ngọc bút là cây bụi lá xanh bóng, hoa trắng cánh kép hoặc đơn thơm nhẹ nở quanh năm. Cây ưa nắng, dễ trồng, hợp hàng rào, sân vườn, trồng chậu lớn.'),
('ti-gon', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng nhẹ; đủ nắng mới ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giảm khi trời mưa"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Chiều cao", "0,5–1m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 3–6m"], ["Công dụng", "Leo giàn, hàng rào, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Antigonon leptopus"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Nhà có giàn, ban công rộng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu lãng mạn", "placement": "Giàn, cổng, ban công"}'::jsonb, '["Hoa tigon", "Coral vine"]'::jsonb, 'Ti gôn thuộc nhóm cây sân vườn. Quy cách: Bầu, cao 0,5–1m.', 'Ti gôn là cây dây leo lá hình tim, hoa nhỏ màu hồng phấn mọc thành chùm dày. Cây lớn rất nhanh, chịu nắng, hợp leo giàn, hàng rào, ban công.'),
('chuoi-mo-ket', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp"], ["Tưới nước", "Giữ đất ẩm, tưới 1 lần/ngày mùa nắng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "0,8–1,2m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 80cm–1,5m, mọc thành bụi"], ["Công dụng", "Sân vườn, bồn cây, cắm hoa"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Vùng Caribe, Nam Mỹ"], ["Tên khoa học", "Heliconia psittacorum"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, resort"]]'::jsonb, '{"mau": ["do-hong", "vang", "co-hoa"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa rực rỡ tượng trưng cho sự may mắn, nhiệt huyết", "placement": "Sân vườn"}'::jsonb, '["Chuối pháo", "Parrot heliconia"]'::jsonb, 'Chuối mỏ két thuộc nhóm cây sân vườn. Quy cách: Bụi, cao 0,8–1,2m.', 'Chuối mỏ két có lá dáng chuối, hoa cam đỏ viền vàng hình mỏ chim mọc thẳng đứng, nở quanh năm. Cây mọc thành bụi, hợp sân vườn nhiệt đới, bồn cây.'),
('chuoi-re-quat', '[["Ánh sáng", "Nắng trực tiếp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giữ ẩm đều"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 3–10m"], ["Công dụng", "Điểm nhấn sân vườn, resort, công trình"], ["Cách nhân giống", "Tách chồi gốc, gieo hạt"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Ravenala madagascariensis"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, resort, khách sạn"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Dáng quạt xòe tượng trưng cho sự phát triển, đón tài lộc", "placement": "Sân vườn, lối vào"}'::jsonb, '["Cây lữ nhân", "Traveller''s palm"]'::jsonb, 'Chuối rẻ quạt thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Chuối rẻ quạt có các tàu lá to xếp thẳng hàng xòe ra như chiếc quạt khổng lồ, rất ấn tượng. Cây hợp làm điểm nhấn sân vườn, resort, công trình.'),
('van-tue', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ"], ["Tưới nước", "Tưới khi đất khô, 2–3 lần/tuần; chịu hạn, kỵ úng"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Rất chậm"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "Không — rất độc với chó mèo (đặc biệt hạt)"], ["Công dụng", "Cổng, sân vườn, công trình, đình chùa"], ["Cách nhân giống", "Tách chồi gốc, gieo hạt"], ["Nguồn gốc", "Nam Nhật Bản"], ["Tên khoa học", "Cycas revoluta"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Biệt thự, công trình, đình chùa"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên \"vạn tuế\" tượng trưng cho sự trường thọ, vững bền", "placement": "Hai bên cổng, sân trước"}'::jsonb, '["Thiên tuế Nhật", "Sago palm"]'::jsonb, 'Vạn tuế thuộc nhóm cây sân vườn, cây công trình. Có 3 quy cách.', 'Vạn tuế có thân to xù xì, lá kép cứng xanh đậm xòe tròn như lông chim, lớn rất chậm và sống hàng trăm năm. Cây trồng chậu cổng, sân vườn, công trình.'),
('cau-vang', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp; trong nhà cần chỗ thật sáng"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1,5–3m, mọc thành bụi"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Phòng khách sáng, sảnh, sân vườn, hồ bơi, công trình"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Dypsis lutescens (syn. Chrysalidocarpus lutescens)"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Gia đình, văn phòng, biệt thự"]]'::jsonb, '{"mau": ["xanh", "vang"], "anhSang": ["nang-nhe", "sang", "nang-gat"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho tài lộc, sung túc; bụi cau xum xuê mang ý nghĩa gia đình đông vui", "placement": "Phòng khách, sảnh, hai bên lối vào"}'::jsonb, '["Cau cảnh", "Dừa cảnh", "Areca palm"]'::jsonb, 'Cau vàng thuộc nhóm cây sân vườn, cây văn phòng, cây trong nhà, cây công trình. Có 4 quy cách.', 'Cau vàng mọc thành bụi nhiều thân, thân và cuống lá ánh vàng, lá kép xòe mềm mại. Cây vừa trồng chậu trang trí phòng khách sáng, vừa trồng sân vườn, hồ bơi.'),
('bach-trinh-bien', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; chịu ẩm tốt"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 40–60cm"], ["An toàn thú cưng", "Không — củ độc với chó mèo"], ["Công dụng", "Trồng thảm, viền bồn, công trình"], ["Cách nhân giống", "Tách củ con"], ["Nguồn gốc", "Châu Mỹ nhiệt đới"], ["Tên khoa học", "Hymenocallis littoralis"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Công trình cảnh quan, sân vườn"]]'::jsonb, '{"mau": ["xanh", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng tượng trưng cho sự trong trắng", "placement": "Bồn hoa sân vườn"}'::jsonb, '["Huệ nhện", "Spider lily"]'::jsonb, 'Bạch trinh biển thuộc nhóm cây sân vườn. Quy cách: Bầu 10cm.', 'Bạch trinh biển có lá dài xanh bóng mọc từ củ, hoa trắng cánh mảnh như chân nhện, thơm nhẹ. Cây chịu nắng, chịu ẩm, trồng thảm, viền bồn, công trình.'),
('co-lan-chi', '[["Ánh sáng", "Nắng nhẹ đến bóng râm nhẹ"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 15–30cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Trồng thảm, viền bồn, chậu treo"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Châu Phi"], ["Tên khoa học", "Chlorophytum"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Công trình cảnh quan, sân vườn"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["nang-nhe", "sang", "nang-gat"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bình an, sinh sôi", "placement": "Bồn viền, ban công"}'::jsonb, '["Lan chi"]'::jsonb, 'Cỏ lan chi thuộc nhóm cây sân vườn. Quy cách: Bầu 8–10cm.', 'Cỏ lan chi có lá dài mảnh viền trắng, mọc thành bụi thấp xanh quanh năm. Cây dễ sống, chịu nắng và bóng, dùng trồng thảm, viền bồn, chậu treo.'),
('thien-dieu', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "0,8–1m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 80cm–1,5m"], ["Công dụng", "Sân vườn, bồn cây, cắm hoa"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Strelitzia reginae"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, resort"]]'::jsonb, '{"mau": ["vang", "tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tự do, thành công, vươn xa", "placement": "Sân vườn, lối vào"}'::jsonb, '["Chim thiên đường", "Bird of paradise"]'::jsonb, 'Thiên điểu thuộc nhóm cây sân vườn. Quy cách: Bụi, cao 0,8–1m.', 'Thiên điểu có hoa cam xanh hình đầu chim đang bay, lá to dày như lá chuối nhỏ. Cây ưa nắng, sống lâu năm, hợp sân vườn, bồn cây, cắm hoa.'),
('cay-sen', '[["Ánh sáng", "Nắng trực tiếp 6 giờ/ngày trở lên để ra hoa"], ["Tưới nước", "Trồng ngập trong chậu, hồ; giữ mực nước ổn định, thay bớt nước khi đục"], ["Đất trồng", "Bùn ao hoặc đất thịt sét, bón lót phân hữu cơ dưới đáy"], ["Bón phân", "Viên phân tan chậm nhét xuống bùn 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Nhanh mùa nắng"], ["Kích thước trưởng thành", "Lá và hoa vươn cao 50cm–1m trên mặt nước"], ["Công dụng", "Hồ tiểu cảnh, chậu nước, sân vườn"], ["Cách nhân giống", "Tách củ, ngó; gieo hạt"], ["Nguồn gốc", "Châu Á"], ["Tên khoa học", "Nelumbo nucifera"], ["Sâu bệnh thường gặp", "Rệp, sâu cuốn lá; ốc ăn lá non"], ["Phù hợp với ai", "Nhà có hồ, sân vườn"]]'::jsonb, '{"mau": ["do-hong", "bac-trang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho sự thanh cao, thuần khiết", "placement": "Hồ nước sân vườn"}'::jsonb, '["Sen", "Lotus"]'::jsonb, 'Cây sen thuộc nhóm cây sân vườn. Quy cách: Củ giống (bầu).', 'Sen là quốc hoa Việt Nam, hoa hồng hoặc trắng thơm ngát vươn cao trên mặt nước. Cây trồng chậu nước, hồ cá, hồ tiểu cảnh, cần nhiều nắng.'),
('sung-kieng', '[["Ánh sáng", "Nắng trực tiếp 6 giờ/ngày trở lên để ra hoa"], ["Tưới nước", "Trồng ngập trong chậu, hồ; giữ mực nước ổn định, thay bớt nước khi đục"], ["Đất trồng", "Bùn ao hoặc đất thịt sét, bón lót phân hữu cơ dưới đáy"], ["Bón phân", "Viên phân tan chậm nhét xuống bùn 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Nhanh mùa nắng"], ["Kích thước trưởng thành", "Lá nổi trên mặt nước, đường kính 15–30cm"], ["Công dụng", "Hồ tiểu cảnh, chậu nước, hồ cá"], ["Cách nhân giống", "Tách củ, ngó; gieo hạt"], ["Nguồn gốc", "Vùng nhiệt đới và ôn đới"], ["Tên khoa học", "Nymphaea"], ["Sâu bệnh thường gặp", "Rệp, sâu cuốn lá; ốc ăn lá non"], ["Phù hợp với ai", "Nhà có hồ, sân vườn"]]'::jsonb, '{"mau": ["do-hong", "tim", "co-hoa"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho sự thanh tịnh, bình yên", "placement": "Hồ nước sân vườn"}'::jsonb, '["Súng", "Water lily"]'::jsonb, 'Súng kiểng thuộc nhóm cây sân vườn. Quy cách: Bầu nhỏ.', 'Súng kiểng có lá tròn nổi trên mặt nước, hoa nhiều màu hồng, tím, trắng, vàng nở trên mặt nước. Cây trồng chậu nước, hồ cá, hồ tiểu cảnh.'),
('kim-giao', '[["Ánh sáng", "Nắng nhẹ đến bóng bán phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "1–1,2m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 2–15m"], ["Công dụng", "Sân vườn, công trình, đình chùa"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Việt Nam, Nam Trung Quốc"], ["Tên khoa học", "Nageia fleuryi"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự che chở, xua điều xấu", "placement": "Sân trước, lối vào"}'::jsonb, '[]'::jsonb, 'Kim giao thuộc nhóm cây sân vườn. Quy cách: Bầu, cao 1–1,2m.', 'Kim giao là cây gỗ quý lá dày bóng xanh đậm, dáng tháp đẹp, gỗ được tin là phát hiện độc. Cây lớn chậm, trồng sân vườn, công trình, đình chùa.'),
('bach-tan', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–20m, tán xếp tầng"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo"], ["Công dụng", "Sân vườn, khuôn viên, cây Noel"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đảo Norfolk (Úc)"], ["Tên khoa học", "Araucaria heterophylla"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tán tầng tượng trưng cho sự thăng tiến từng bước", "placement": "Sân vườn, lối vào"}'::jsonb, '["Tùng bách tán", "Norfolk pine"]'::jsonb, 'Bách tán thuộc nhóm cây sân vườn. Quy cách: Cao 1,5–2m, 5–6 tầng.', 'Bách tán có tán xếp thành từng tầng cành ngang đều như những chiếc ô, dáng tháp cân đối. Cây trồng sân vườn, khuôn viên, cũng hay làm cây thông Noel trong chậu.'),
('cha-la-canh', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Chiều cao", "1,5–2m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1,5–3m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc); cuống lá có gai"], ["Công dụng", "Sân vườn, hồ bơi, resort, công trình"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Lào, Việt Nam, Nam Trung Quốc"], ["Tên khoa học", "Phoenix roebelenii"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Biệt thự, resort, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sung túc, bền bỉ", "placement": "Sân vườn, lối vào"}'::jsonb, '["Chà là lùn", "Pygmy date palm"]'::jsonb, 'Chà là cảnh thuộc nhóm cây sân vườn. Quy cách: Thân 30–50cm, cao 1,5–2m.', 'Chà là cảnh có thân mảnh, tán lá kép mềm xòe tròn ở ngọn, cuống lá có gai. Cây chịu nắng, dáng đẹp, hợp sân vườn, hồ bơi, resort, sảnh ngoài trời.'),
('sao-den', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 20–40m khi trưởng thành"], ["Công dụng", "Cây đường phố, công viên, trường học, rừng trồng"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đông Nam Á (có ở Việt Nam)"], ["Tên khoa học", "Hopea odorata"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vững chãi, trường tồn", "placement": "Đường, công viên"}'::jsonb, '["Sao"]'::jsonb, 'Sao đen thuộc nhóm cây công trình. Có 2 quy cách.', 'Sao đen là cây gỗ lớn bản địa, thân thẳng, tán gọn, gỗ quý; hoa nhỏ thơm. Cây sống lâu, chịu gió, trồng nhiều làm cây đường phố, công viên ở miền Nam.'),
('dau-rai', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 25–40m khi trưởng thành"], ["Công dụng", "Cây đường phố, công viên, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đông Nam Á (có ở Việt Nam)"], ["Tên khoa học", "Dipterocarpus alatus"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vững chãi", "placement": "Đường, công viên"}'::jsonb, '["Dầu con rái", "Dầu nước"]'::jsonb, 'Dầu rái thuộc nhóm cây công trình. Có 2 quy cách.', 'Dầu rái là cây gỗ lớn bản địa, thân thẳng tròn, tán cao, quả có hai cánh xoay khi rơi. Cây sống lâu, trồng làm cây đường phố, công viên, khuôn viên lớn.'),
('xa-cu', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 15–30m"], ["Công dụng", "Bóng mát khuôn viên rộng, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Tây Phi"], ["Tên khoa học", "Khaya senegalensis"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, khuôn viên rộng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự che chở", "placement": "Khuôn viên rộng"}'::jsonb, '["Sọ khỉ", "African mahogany"]'::jsonb, 'Xà cừ thuộc nhóm cây công trình. Có 2 quy cách.', 'Xà cừ là cây gỗ lớn tán rộng xanh đậm, lớn nhanh, chịu nắng hạn, từng được trồng nhiều làm cây đường phố. Cây hợp khuôn viên rộng, xa nhà ở vì rễ khỏe.'),
('long-nao', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 10–20m"], ["Công dụng", "Cây đường phố, công viên, trường học"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đông Á"], ["Tên khoa học", "Cinnamomum camphora"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Mùi thơm tượng trưng cho sự thanh lọc, xua tà", "placement": "Đường, công viên"}'::jsonb, '["Dã hương", "Camphor tree"]'::jsonb, 'Long não thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Long não là cây gỗ tán tròn dày, lá xanh bóng có mùi thơm long não khi vò. Cây sống lâu, ít rụng lá, trồng làm cây đường phố, công viên, trường học.'),
('bang-lang', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 5–15m"], ["Công dụng", "Cây đường phố, sân trường, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Lagerstroemia speciosa"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["tim", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa tím tượng trưng cho tình yêu thủy chung, tuổi học trò", "placement": "Đường, sân trường"}'::jsonb, '["Bằng lăng nước", "Queen''s crape myrtle"]'::jsonb, 'Bằng lăng thuộc nhóm cây công trình. Có 2 quy cách.', 'Bằng lăng có hoa tím thành chùm lớn nở rộ vào mùa hè, lá chuyển đỏ trước khi rụng. Cây cho bóng mát và hoa đẹp, trồng nhiều làm cây đường phố, sân trường.'),
('phuong-vi', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 8–15m, tán rộng"], ["Công dụng", "Sân trường, công viên, đường phố"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Delonix regia"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, trường học"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa đỏ tượng trưng cho tuổi học trò, sự nhiệt huyết", "placement": "Sân trường, công viên"}'::jsonb, '["Phượng đỏ", "Flamboyant"]'::jsonb, 'Phượng vĩ thuộc nhóm cây công trình. Có 2 quy cách.', 'Phượng vĩ có tán rộng như chiếc ô, lá kép nhỏ li ti, hoa đỏ rực nở vào mùa hè, gắn với tuổi học trò. Cây cho bóng mát lớn, trồng sân trường, công viên, đường phố.'),
('me-tay', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 15–25m, tán rất rộng"], ["Công dụng", "Bóng mát công viên, khuôn viên rộng"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Trung Mỹ, Nam Mỹ"], ["Tên khoa học", "Samanea saman"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, khuôn viên rộng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tán rộng tượng trưng cho sự che chở", "placement": "Công viên, khuôn viên"}'::jsonb, '["Cây mưa", "Rain tree"]'::jsonb, 'Me tây thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Me tây có tán rất rộng hình ô, lá kép khép lại khi trời tối hoặc mưa. Cây lớn nhanh, cho bóng mát lớn, trồng công viên, khuôn viên rộng.'),
('hoa-sua', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "60–80cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–20m"], ["Công dụng", "Cây đường phố, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Alstonia scholaris"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, khuôn viên rộng"]]'::jsonb, '{"mau": ["xanh", "bac-trang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Gắn với hình ảnh mùa thu Hà Nội", "placement": "Công viên, xa nhà ở"}'::jsonb, '["Mò cua", "Devil tree"]'::jsonb, 'Hoa sữa thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 60–80cm.', 'Hoa sữa có tán xếp tầng, lá mọc vòng, hoa trắng xanh nhỏ nở vào cuối thu với mùi hương rất nồng. Cây lớn nhanh; nên trồng xa nhà ở, cửa sổ phòng ngủ vì mùi hoa có thể gây khó chịu.'),
('cau-vua', '[["Ánh sáng", "Nắng trực tiếp"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày; cây lớn chịu hạn khá"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 10–25m, thân thẳng như cột"], ["Công dụng", "Hàng cây đường lớn, cổng, khuôn viên, resort"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Cuba, vùng Caribe"], ["Tên khoa học", "Roystonea regia"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Công trình, biệt thự, resort"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Dáng thẳng cao tượng trưng cho sự vững vàng, thịnh vượng", "placement": "Hai bên đường vào, cổng"}'::jsonb, '["Cau bụng", "Royal palm"]'::jsonb, 'Cau vua thuộc nhóm cây công trình, cây sân vườn. Có 3 quy cách.', 'Cau vua có thân thẳng tròn màu xám bạc như cột, phình nhẹ ở giữa, tán lá kép lớn ở ngọn. Cây bề thế, trồng thành hàng dọc đường lớn, cổng, khuôn viên.'),
('tung-la-han', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 1–5m"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Cây dáng thế sân vườn, cổng, hàng rào, bonsai"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Trung Quốc, Nhật Bản"], ["Tên khoa học", "Podocarpus macrophyllus"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình, người chơi cây cảnh"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự trường thọ, vững vàng, bảo vệ gia đình", "placement": "Hai bên cổng, sân trước"}'::jsonb, '["Buddhist pine"]'::jsonb, 'Tùng la hán thuộc nhóm cây công trình, cây sân vườn. Có 3 quy cách.', 'Tùng la hán có lá dài hẹp xanh đậm mọc dày, thân gỗ chắc, sống rất lâu năm. Cây dễ cắt tỉa tạo dáng, trồng chậu sân vườn, cổng, hàng rào hoặc bonsai.'),
