('me-ta', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 5–15m (trồng chậu 1,5–2m)"], ["Công dụng", "Bóng mát, lấy trái, bonsai"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Tamarindus indica"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân rộng, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bền bỉ, sung túc", "placement": "Sân vườn"}'::jsonb, '["Me", "Tamarind"]'::jsonb, 'Me ta thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Me ta là cây gỗ lá kép nhỏ, tán rộng, chịu nắng hạn, sống lâu năm. Cây con bầu ươm thích hợp trồng bóng mát công trình, đường, sân trường.'),
('o-moi', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 10–20m"], ["Công dụng", "Cây đường phố, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Trung Mỹ, Nam Mỹ"], ["Tên khoa học", "Cassia grandis"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa hồng tượng trưng cho tình cảm quê hương miền Tây", "placement": "Đường, công viên"}'::jsonb, '["Bò cạp nước", "Pink shower"]'::jsonb, 'Ô môi thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Ô môi có hoa hồng phấn nở rộ phủ kín tán vào mùa khô, quả dài màu nâu đen. Cây quen thuộc ở miền Tây, trồng cây đường phố, công viên.'),
('bang-vuong', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 7–20m"], ["Công dụng", "Bóng mát ven biển, công viên, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Ven biển Ấn Độ Dương, Thái Bình Dương"], ["Tên khoa học", "Barringtonia asiatica"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình ven biển, đô thị"]]'::jsonb, '{"mau": ["xanh-dam", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vững chãi", "placement": "Công viên"}'::jsonb, '["Bàng bí", "Box fruit"]'::jsonb, 'Bàng vuông thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Bàng vuông có lá to bóng, hoa trắng nhụy dài hồng nở về đêm, quả hình hộp vuông. Cây chịu gió, chịu mặn, trồng ven biển, công viên, khuôn viên.'),
('bo-de', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 15–25m"], ["An toàn thú cưng", "Nhựa trắng gây kích ứng"], ["Công dụng", "Đình chùa, công viên, khuôn viên rộng"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Ấn Độ, Đông Nam Á"], ["Tên khoa học", "Ficus religiosa"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Đình chùa, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Biểu tượng của sự giác ngộ, bình an", "placement": "Đình chùa, khuôn viên rộng"}'::jsonb, '["Sacred fig"]'::jsonb, 'Bồ đề thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Bồ đề có lá hình tim với đuôi lá dài nhọn, gắn liền với Phật giáo. Cây sống lâu, tán rộng, trồng ở đình chùa, khuôn viên rộng, xa nhà ở vì rễ khỏe.'),
('phi-lao', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "40–60cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 15–30m"], ["Công dụng", "Chắn gió, chắn cát ven biển, rừng phòng hộ"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Úc, Đông Nam Á, Thái Bình Dương"], ["Tên khoa học", "Casuarina equisetifolia"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình ven biển"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự kiên cường", "placement": "Ven biển"}'::jsonb, '["Dương liễu", "Casuarina"]'::jsonb, 'Phi lao thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 40–60cm.', 'Phi lao có cành nhỏ như lá kim rủ mềm, chịu gió cát và đất mặn rất tốt. Cây trồng chắn gió ven biển, chắn cát, làm hàng rào chắn gió.'),
('so-do-cam', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–20m"], ["Công dụng", "Cây đường phố, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Spathodea campanulata"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa cam đỏ tượng trưng cho sự nhiệt huyết", "placement": "Đường, công viên"}'::jsonb, '["Hồng kỳ", "African tulip tree"]'::jsonb, 'Sò đo cam thuộc nhóm cây công trình. Quy cách: Bầu ươm, cao 50–70cm.', 'Sò đo cam có hoa cam đỏ hình chuông lớn nở thành chùm trên ngọn, rất rực rỡ. Cây lớn nhanh, trồng cây đường phố, công viên.'),
('kim-ngan', '[["Ánh sáng", "Ánh sáng tán xạ sáng đến nắng nhẹ"], ["Tưới nước", "Tưới khi đất khô 3–4cm, 1–2 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Trang trí văn phòng, phòng khách, cửa hàng; quà khai trương"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Trung và Nam Mỹ"], ["Tên khoa học", "Pachira aquatica"], ["Sâu bệnh thường gặp", "Rụng lá khi đổi chỗ đột ngột hoặc úng nước; rệp sáp"], ["Phù hợp với ai", "Văn phòng, kinh doanh, nhà có thú cưng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Thân tết bện tượng trưng cho tài lộc tụ lại, công việc hanh thông", "placement": "Bàn làm việc, quầy thu ngân, góc Đông Nam"}'::jsonb, '["Money tree", "Bình bát nước"]'::jsonb, 'Kim ngân thuộc nhóm cây văn phòng, cây trong nhà, cây ban công. Quy cách: Cao 50–70cm.', 'Kim ngân có thân thường được tết bện 3–5 thân, lá kép xòe như bàn tay xanh tươi. Cây chịu bóng khá, dễ chăm, là cây phong thủy phổ biến nơi văn phòng, cửa hàng.'),
('bach-ma-hoang-tu', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 40–80cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí phòng khách, văn phòng; quà tặng thăng chức"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Aglaonema pseudobracteatum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Văn phòng, gia đình"]]'::jsonb, '{"mau": ["bac-trang", "xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho sự thành đạt, thăng tiến, phong thái lịch lãm", "placement": "Bàn làm việc, phòng khách"}'::jsonb, '["Aglaonema White Stem"]'::jsonb, 'Bạch mã hoàng tử thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–70cm.', 'Bạch mã hoàng tử có cuống và gân lá trắng nổi bật trên nền lá xanh, dáng thẳng thanh lịch. Cây chịu bóng, dễ chăm, hợp đặt phòng khách, văn phòng.'),
('trau-ba-de-vuong-xanh', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50–100cm, tán rộng"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí sảnh, phòng khách, văn phòng; quà tặng"], ["Cách nhân giống", "Tách chồi con"], ["Nguồn gốc", "Nam Mỹ (giống lai)"], ["Tên khoa học", "Philodendron ''Imperial Green''"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Văn phòng, gia đình muốn cây lá to sang trọng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi và dáng lá uy nghi tượng trưng cho quyền lực, thịnh vượng, thăng tiến", "placement": "Phòng khách, phòng giám đốc, sảnh"}'::jsonb, '["Đế vương", "Philodendron Imperial"]'::jsonb, 'Trầu bà đế vương xanh thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–70cm.', 'Trầu bà đế vương xanh có lá to bản xanh đậm bóng, mọc xòe đều quanh gốc. Cây khỏe, chịu bóng, hợp trang trí phòng khách, sảnh văn phòng.'),
('trau-ba-de-vuong-do', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50–100cm, tán rộng"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí sảnh, phòng khách, văn phòng; quà tặng"], ["Cách nhân giống", "Tách chồi con"], ["Nguồn gốc", "Nam Mỹ (giống lai)"], ["Tên khoa học", "Philodendron ''Imperial Red''"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Văn phòng, gia đình muốn cây lá to sang trọng"]]'::jsonb, '{"mau": ["do-hong", "xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ tượng trưng cho may mắn, thịnh vượng, quyền uy", "placement": "Phòng khách, phòng giám đốc, sảnh"}'::jsonb, '["Đế vương", "Philodendron Imperial"]'::jsonb, 'Trầu bà đế vương đỏ thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–70cm.', 'Trầu bà đế vương đỏ có lá non màu đỏ tía, khi già chuyển xanh đỏ đậm, rất nổi bật. Cây khỏe, chịu bóng, hợp đặt phòng khách, sảnh.'),
('trau-ba-la-xe', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 50–100cm, tán rộng 1m"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí góc phòng, sảnh, văn phòng"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Philodendron xanadu"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng thích phong cách nhiệt đới"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá xòe rộng tượng trưng cho sự phát triển, đón tài lộc", "placement": "Góc phòng khách, sảnh"}'::jsonb, '["Trầu bà lá rách", "Philodendron Xanadu"]'::jsonb, 'Trầu bà lá xẻ thuộc nhóm cây văn phòng. Quy cách: Cao 50–70cm.', 'Trầu bà lá xẻ có lá xẻ thùy sâu, mọc thành bụi tròn, nhìn tươi mát và hiện đại. Cây chịu bóng, ít sâu bệnh, hợp đặt góc phòng khách.'),
('monstera', '[["Ánh sáng", "Ánh sáng tán xạ sáng; chịu bóng nhưng lá ít xẻ hơn"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 1–2m trong chậu (cần cột cho leo)"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Cây điểm nhấn phòng khách, quán cà phê, văn phòng"], ["Cách nhân giống", "Giâm đốt thân có rễ khí"], ["Nguồn gốc", "Trung Mỹ (Mexico đến Panama)"], ["Tên khoa học", "Monstera deliciosa"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích phong cách nhiệt đới, không gian rộng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá to xòe rộng tượng trưng cho sự phát triển, sung túc", "placement": "Góc phòng khách sáng, sảnh"}'::jsonb, '["Trầu bà Nam Mỹ", "Swiss cheese plant"]'::jsonb, 'Monstera thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–80cm.', 'Monstera có lá to, xẻ thùy và thủng lỗ rất đặc trưng, là biểu tượng của phong cách nội thất nhiệt đới. Cây lớn nhanh, có rễ khí bám cột, hợp đặt góc phòng sáng.'),
('luoi-ho-vang', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ; chịu bóng râm, đèn văn phòng"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; lá mọng nước, rất chịu hạn"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 50–120cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất, đặt phòng ngủ, văn phòng, lối vào"], ["Cách nhân giống", "Tách bụi, giâm lá"], ["Nguồn gốc", "Tây Phi nhiệt đới"], ["Tên khoa học", "Dracaena trifasciata ''Laurentii''"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, hay đi công tác, ít thời gian"]]'::jsonb, '{"mau": ["loang", "vang"], "anhSang": ["sang", "ram", "den", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Viền vàng tượng trưng cho tài lộc, cây mọc thẳng mang ý nghĩa vững vàng, bảo vệ", "placement": "Lối vào, bàn làm việc, phòng khách"}'::jsonb, '["Hổ vĩ", "Snake plant", "Sansevieria"]'::jsonb, 'Lưỡi hổ vàng thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–70cm.', 'Lưỡi hổ vàng là giống lưỡi hổ viền lá vàng tươi, nổi bật hơn lưỡi hổ thường. Cây khỏe, chịu hạn, chịu thiếu sáng, hợp đặt văn phòng và phòng khách.'),
('lan-y', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần; lá rũ là dấu hiệu cần tưới"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí phòng khách, phòng ngủ, văn phòng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Trung và Nam Mỹ nhiệt đới"], ["Tên khoa học", "Spathiphyllum wallisii"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh-dam", "co-hoa", "bac-trang"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng tượng trưng cho sự bình yên, thanh khiết, hòa hợp", "placement": "Phòng khách, phòng ngủ, bàn làm việc"}'::jsonb, '["Bạch môn", "Huệ hòa bình", "Peace lily"]'::jsonb, 'Lan ý thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 40–60cm.', 'Lan ý có lá xanh đậm bóng và hoa mo trắng thanh khiết vươn cao, ra hoa được trong nhà. Cây chịu bóng, nằm trong danh sách cây lọc không khí nổi tiếng, hợp phòng khách, phòng ngủ.'),
('thiet-moc-lan', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh; quà khai trương"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans ''Massangeana''"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng muốn cây cao dễ chăm"]]'::jsonb, '{"mau": ["loang", "vang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa phát tài phát lộc, làm ăn thuận lợi", "placement": "Phòng khách, phòng làm việc, góc Đông Nam"}'::jsonb, '["Phát tài", "Mass cane"]'::jsonb, 'Thiết mộc lan thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Thiết mộc lan là giống phát tài lá có sọc vàng giữa phiến, thân gỗ thẳng, có thể trồng nhiều thân cao thấp trong một chậu. Cây trưởng thành ra chùm hoa trắng thơm, được xem là điềm may.'),
('phat-tai-nui', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp; trong nhà cần chỗ thật sáng"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/tuần; rất chịu hạn"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 1–3m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Cây điểm nhấn sảnh, sân vườn, tiểu cảnh"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Quần đảo Canary, Bắc Phi"], ["Tên khoa học", "Dracaena draco"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Biệt thự, văn phòng, công trình cần cây dáng đẹp lâu năm"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat", "sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Thân gỗ vững chãi tượng trưng cho sự bền vững, tài lộc lâu dài", "placement": "Sảnh, lối vào, sân vườn"}'::jsonb, '["Huyết giác", "Dragon tree"]'::jsonb, 'Phát tài núi thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Phát tài núi có thân gỗ to, sần, phân nhánh, lá dài cứng mọc thành chùm ở ngọn, dáng cổ thụ rất bề thế. Cây chịu hạn, chịu nắng, hợp đặt sảnh lớn, sân vườn, công trình.'),
('phat-tai-khuc', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh; quà khai trương"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng muốn cây cao dễ chăm"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa phát tài phát lộc, làm ăn thuận lợi", "placement": "Phòng khách, phòng làm việc, góc Đông Nam"}'::jsonb, '["Phát tài thân khúc", "Thiết mộc lan khúc"]'::jsonb, 'Phát tài khúc thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 80–120cm.', 'Phát tài khúc gồm các khúc thân gỗ cắt ngang, mỗi khúc đâm chồi lá xanh ở đầu, thường trồng 3–5 khúc cao thấp trong một chậu. Cây chịu bóng, ít sâu bệnh, hợp phòng khách, văn phòng.'),
('dai-phu-gia', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 50cm–1m"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí phòng khách, sảnh, văn phòng; quà khai trương"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Á, Đông Nam Á"], ["Tên khoa học", "Aglaonema sp"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho thịnh vượng, may mắn, tài lộc", "placement": "Hướng Nam hoặc Đông Nam phòng khách"}'::jsonb, '["Aglaonema"]'::jsonb, 'Đại phú gia thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Đại phú gia có thân mập, mọng nước, lá to hình bầu dục xanh bóng tập trung ở ngọn; cây có thể ra hoa trắng ngà thơm. Cây ưa mát, chịu bóng, hợp đặt phòng khách, sảnh.'),
('hanh-phuc', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 70cm–2m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Phòng khách, sảnh, văn phòng; quà tân gia, cưới hỏi"], ["Cách nhân giống", "Giâm cành"], ["Nguồn gốc", "Nam Trung Quốc, Đài Loan"], ["Tên khoa học", "Radermachera sinica"], ["Sâu bệnh thường gặp", "Rụng lá khi đổi chỗ đột ngột, thiếu sáng hoặc úng; rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng, nhà có thú cưng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho hạnh phúc, gia đình êm ấm, sum vầy", "placement": "Phòng khách, góc Đông"}'::jsonb, '["Cây hạnh phúc", "China doll"]'::jsonb, 'Hạnh phúc thuộc nhóm cây văn phòng, cây trong nhà. Có 2 quy cách.', 'Cây hạnh phúc có thân gỗ thẳng, lá kép xanh bóng mọc tầng tầng, dáng thanh lịch. Cây hợp đặt phòng khách, sảnh, thường làm quà tân gia, cưới hỏi.'),
('cau-hawai', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp; trong nhà cần chỗ thật sáng"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1,5–3m, mọc thành bụi"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Phòng khách sáng, sảnh, sân vườn, hồ bơi, công trình"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Dypsis lutescens (syn. Chrysalidocarpus lutescens)"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Gia đình, văn phòng, biệt thự"]]'::jsonb, '{"mau": ["xanh", "vang"], "anhSang": ["nang-nhe", "sang", "nang-gat"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho tài lộc, sung túc; bụi cau xum xuê mang ý nghĩa gia đình đông vui", "placement": "Phòng khách, sảnh, hai bên lối vào"}'::jsonb, '["Cau vàng", "Cau cảnh", "Areca palm"]'::jsonb, 'Cau Hawai thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Cau Hawai (cau cảnh) mọc thành bụi nhiều thân, lá kép xanh mướt xòe rộng, thân ánh vàng. Cây hợp trang trí phòng khách sáng, sảnh văn phòng và sân vườn.'),
('cau-nhat', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ; cây trong nhà nên đặt gần cửa sổ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["Công dụng", "Trang trí phòng khách, sảnh, văn phòng"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sinh sôi, may mắn", "placement": "Phòng khách, sảnh"}'::jsonb, '[]'::jsonb, 'Cau Nhật thuộc nhóm cây văn phòng. Quy cách: Cao 80–120cm.', 'Cau Nhật là loại cau cảnh dáng gọn, lá kép xanh mướt, thường trồng chậu trang trí trong nhà và sảnh. Cây ưa sáng tán xạ, dễ chăm.'),
('co-nhat', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ; cây trong nhà nên đặt gần cửa sổ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["Công dụng", "Trang trí phòng khách, sảnh, sân vườn"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá xòe như quạt tượng trưng cho sự che chở, bình an", "placement": "Sảnh, phòng khách"}'::jsonb, '[]'::jsonb, 'Cọ Nhật thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Cọ Nhật có lá hình quạt xẻ sâu, mọc thành bụi, dáng gọn. Cây chịu bóng khá tốt, hợp trồng chậu trong nhà sáng, sảnh và sân vườn.'),
('co-ta', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–10m ngoài tự nhiên; trồng chậu 1–2m"], ["Công dụng", "Sân vườn, công viên, resort, công trình"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Đông Nam Á (có ở Việt Nam)"], ["Tên khoa học", "Livistona saribus"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Biệt thự, công trình cảnh quan"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá quạt tượng trưng cho sự che chở, bình an", "placement": "Sân vườn, lối vào"}'::jsonb, '["Cọ", "Kè nam", "Cây lá gồi"]'::jsonb, 'Cọ ta thuộc nhóm cây văn phòng, cây sân vườn, cây công trình. Có 3 quy cách.', 'Cọ ta là loài cọ bản địa, lá hình quạt to xẻ thùy, cuống có gai. Cây khỏe, chịu nắng gió, hợp trồng sân vườn, công trình, resort.'),
('truc-nhat', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50cm–1m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất, hành lang, tiểu cảnh"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Tây Phi"], ["Tên khoa học", "Dracaena surculosa"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Dáng trúc tượng trưng cho người quân tử, ngay thẳng, bình an", "placement": "Phòng khách, hành lang"}'::jsonb, '["Phất dụ trúc", "Trúc phất dụ", "Gold dust dracaena"]'::jsonb, 'Trúc Nhật thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn. Có 2 quy cách.', 'Trúc Nhật mọc thành bụi, thân chia đốt như trúc, lá hình thoi bóng, thường có đốm vàng. Cây chịu bóng, ít sâu bệnh, hợp đặt góc phòng, hành lang.'),
('truc-may', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ; chịu bóng tốt"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 1–3m, mọc thành bụi"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Phòng khách, sảnh, hành lang, sân vườn bóng râm"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Nam Trung Quốc, Đài Loan"], ["Tên khoa học", "Rhapis excelsa"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Gia đình, văn phòng, nhà có thú cưng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Dáng trúc tượng trưng cho người quân tử, ngay thẳng; bụi cây xum xuê mang ý nghĩa sung túc", "placement": "Phòng khách, sảnh, góc Đông"}'::jsonb, '["Mật cật", "Lady palm"]'::jsonb, 'Trúc Mây thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Trúc mây mọc thành bụi nhiều thân mảnh như trúc, lá hình quạt xẻ ngón xanh đậm. Cây chịu bóng, ít sâu bệnh, sống lâu năm, hợp đặt phòng khách, sảnh.'),
('truc-bach-hop', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Madagascar, các đảo Ấn Độ Dương"], ["Tên khoa học", "Dracaena reflexa"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["loang", "vang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự thanh cao, may mắn, sức khỏe", "placement": "Phòng khách, phòng làm việc"}'::jsonb, '["Bách hợp", "Song of India"]'::jsonb, 'Trúc Bách Hợp thuộc nhóm cây văn phòng. Quy cách: Cao 50–80cm.', 'Trúc bách hợp có thân mảnh phân cành, lá xếp xoắn quanh thân, nhiều giống viền vàng tươi. Cây chịu bóng, giúp làm mát không gian, hợp đặt phòng khách, văn phòng.'),
('ngu-gia-bi-vang', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, ban công, sân vườn; trồng viền"], ["Cách nhân giống", "Giâm cành"], ["Nguồn gốc", "Đài Loan, Hải Nam (Trung Quốc)"], ["Tên khoa học", "Heptapleurum arboricola ''Gold Capella''"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["loang", "vang"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Sắc vàng tượng trưng cho tài lộc; lá xòe như bàn tay mang ý nghĩa đoàn kết, che chở", "placement": "Phòng khách, ban công"}'::jsonb, '["Chân chim", "Schefflera"]'::jsonb, 'Ngũ gia bì vàng thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–80cm.', 'Ngũ gia bì vàng là giống ngũ gia bì lá đốm vàng tươi, sáng màu hơn giống lá xanh. Cây cần chỗ sáng để giữ màu lá đẹp.'),
('duoi-phung', '[["Ánh sáng", "Ánh sáng tán xạ nhẹ; nắng trực tiếp làm bạc, cháy lá"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần; dùng nước để lắng qua đêm"], ["Đất trồng", "Đất giàu mùn, tơi xốp, giữ ẩm nhưng thoát nước tốt"], ["Bón phân", "NPK cân đối pha loãng, 1 lần/tháng trong mùa sinh trưởng"], ["Chiều cao", "30–50cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–30°C, ưa ẩm cao; phun sương khi không khí khô"], ["Mức độ dễ chăm", "Trung bình — cần giữ ẩm đều"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn, kệ, góc phòng mát"], ["Cách nhân giống", "Tách bụi khi thay chậu"], ["Nguồn gốc", "Đông Brazil"], ["Tên khoa học", "Goeppertia lancifolia (syn. Calathea lancifolia)"], ["Sâu bệnh thường gặp", "Cháy mép lá khi không khí khô, nhện đỏ, rệp sáp"], ["Phù hợp với ai", "Người thích cây lá hoa văn, nhà có thú cưng"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["sang", "ram"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sung túc, may mắn", "placement": "Phòng khách, phòng làm việc"}'::jsonb, '["Calathea lancifolia", "Rattlesnake plant"]'::jsonb, 'Đuôi phụng thuộc nhóm cây văn phòng. Quy cách: Cao 30–50cm.', 'Đuôi phụng có lá dài thuôn, mép gợn sóng, hoa văn đốm xanh đậm xen kẽ như lông chim, mặt dưới tím. Cây ưa bóng mát, ẩm, an toàn với thú cưng.'),
('ngan-hau', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "30–50cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, kệ, góc phòng, văn phòng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Aglaonema (giống Silver Queen)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng ít sáng"]]'::jsonb, '{"mau": ["bac-trang", "xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Sắc bạc tượng trưng cho sự sang trọng, bình an, tài lộc", "placement": "Phòng khách, bàn làm việc"}'::jsonb, '["Aglaonema Silver Queen"]'::jsonb, 'Ngân hậu thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 30–50cm.', 'Ngân hậu có lá thuôn dài phủ mảng bạc xen xanh, mọc thành bụi gọn. Cây chịu bóng rất tốt, dễ sống trong văn phòng máy lạnh.'),
('thanh-tam', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "30–50cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, kệ, phòng khách, văn phòng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa tâm an, thanh tịnh", "placement": "Phòng làm việc, phòng khách"}'::jsonb, '[]'::jsonb, 'Thanh tâm thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 30–50cm.', 'Thanh tâm là cây lá nội thất họ Ráy, lá xanh mát, mọc thành bụi gọn. Cây chịu bóng, dễ chăm, hợp đặt bàn, kệ, phòng khách.'),
('van-nien-thanh-leo-cot', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 60cm–1,5m (leo cột)"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột trang trí góc phòng, sảnh"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vươn lên, phát triển", "placement": "Góc phòng khách, sảnh"}'::jsonb, '["Trầu bà leo cột"]'::jsonb, 'Vạn niên thanh leo cột thuộc nhóm cây văn phòng. Quy cách: Cao 80–120cm.', 'Vạn niên thanh leo là cây dây leo họ Ráy được trồng leo cột, lá xanh bóng mọc dày quanh trụ. Cây chịu bóng, lớn nhanh, hợp đặt góc phòng, sảnh.'),
('thuong-xuan', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Ưa mát 15–28°C; nắng nóng gắt dễ khô lá"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Dây dài 1–2m"], ["An toàn thú cưng", "Không — độc với chó mèo nếu ăn phải"], ["Công dụng", "Chậu treo, kệ, leo tường, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Châu Âu, Tây Á"], ["Tên khoa học", "Hedera helix"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Căn hộ, ban công ít nắng"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa xanh tươi bền lâu, tình cảm gắn bó", "placement": "Kệ cao, ban công, cửa sổ"}'::jsonb, '["Dây thường xuân", "Ivy"]'::jsonb, 'Thường xuân thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà, cây ban công. Có 3 quy cách.', 'Thường xuân là cây dây leo lá chia thùy hình ngôi sao, có giống viền trắng, dây mềm rủ đẹp. Cây hợp chậu treo, kệ cao, ban công ít nắng gắt.'),
('nha-dam', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — độc với chó mèo nếu ăn phải"], ["Công dụng", "Trang trí ban công, cửa sổ, bàn sáng"], ["Cách nhân giống", "Tách cây con mọc quanh gốc"], ["Nguồn gốc", "Bán đảo Ả Rập"], ["Tên khoa học", "Aloe vera"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, ban công nắng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sức khỏe, sự bảo vệ", "placement": "Ban công, cửa sổ, bếp sáng"}'::jsonb, '["Lô hội", "Aloe vera"]'::jsonb, 'Nha đam thuộc nhóm cây văn phòng, cây trong nhà, cây ban công. Quy cách: Cao 30–50cm.', 'Nha đam có lá dày mọng nước, mép có răng cưa, bên trong chứa gel trong. Cây rất chịu hạn, ưa nắng, dễ trồng ở bàn cửa sổ, ban công.'),
('ngoc-bich', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–60cm, thân hóa gỗ"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo"], ["Công dụng", "Để bàn, cửa sổ, ban công, bonsai mini"], ["Cách nhân giống", "Giâm cành, giâm lá"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Crassula ovata"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, bàn có nắng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá tròn như đồng xu tượng trưng cho tiền tài, sung túc", "placement": "Bàn làm việc gần cửa sổ, góc Đông Nam"}'::jsonb, '["Cây ngọc bích", "Jade plant", "Cây tiền"]'::jsonb, 'Ngọc bích thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà. Có 2 quy cách.', 'Ngọc bích có lá dày tròn mọng nước xanh bóng như ngọc, thân hóa gỗ theo thời gian, có thể tạo dáng bonsai. Cây chịu hạn, ưa nắng sáng, sống rất lâu năm.'),
('nhat-mat-huong', '[["Ánh sáng", "Nắng nhẹ đến sáng tán xạ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; lá mọng nên chịu hạn khá"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 15–40cm"], ["Công dụng", "Để bàn, cửa sổ, ban công nhỏ"], ["Cách nhân giống", "Giâm ngọn"], ["Nguồn gốc", "Nam Phi, Đông Phi"], ["Tên khoa học", "Plectranthus hadiensis var. tomentosus"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người thích cây có mùi thơm"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "sang"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Mùi thơm tượng trưng cho sự thanh lọc, may mắn", "placement": "Bàn làm việc, cửa sổ"}'::jsonb, '["Húng chanh lá nhỏ", "Cây thơm"]'::jsonb, 'Nhất mạt hương thuộc nhóm cây văn phòng, cây để bàn, cây trong nhà. Có 2 quy cách.', 'Nhất mạt hương có lá nhỏ dày phủ lông mịn, vò nhẹ tỏa mùi thơm dễ chịu, được tin là giúp xua muỗi. Cây nhỏ gọn, dễ trồng, hợp để bàn, cửa sổ.'),
('cam-nhung', '[["Ánh sáng", "Ánh sáng tán xạ nhẹ; nắng trực tiếp làm bạc, cháy lá"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần; dùng nước để lắng qua đêm"], ["Đất trồng", "Đất giàu mùn, tơi xốp, giữ ẩm nhưng thoát nước tốt"], ["Bón phân", "NPK cân đối pha loãng, 1 lần/tháng trong mùa sinh trưởng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–30°C, ưa ẩm cao; phun sương khi không khí khô"], ["Mức độ dễ chăm", "Trung bình — cần giữ ẩm đều"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 10–20cm, bò lan"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn, tiểu cảnh bể kính (terrarium)"], ["Cách nhân giống", "Giâm ngọn"], ["Nguồn gốc", "Peru, Colombia"], ["Tên khoa học", "Fittonia albivenis"], ["Sâu bệnh thường gặp", "Cháy mép lá khi không khí khô, nhện đỏ, rệp sáp"], ["Phù hợp với ai", "Người thích cây nhỏ lá hoa văn"]]'::jsonb, '{"mau": ["loang", "xanh"], "anhSang": ["sang", "ram"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự may mắn, tinh tế", "placement": "Bàn làm việc, kệ"}'::jsonb, '["Lá may mắn", "Fittonia", "Nerve plant"]'::jsonb, 'Cẩm nhung thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 10–20cm.', 'Cẩm nhung có lá nhỏ với mạng gân trắng hoặc đỏ nổi bật như dệt lưới. Cây nhỏ, ưa bóng mát và ẩm, hợp để bàn, bể kính tiểu cảnh.'),
('tung-thom', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp; trong nhà đặt cạnh cửa sổ sáng"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 1 lần/ngày mùa nắng; không để khô kiệt"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Ưa mát; nắng nóng gắt kéo dài dễ cháy ngọn"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30cm–1,5m, dáng tháp"], ["Công dụng", "Ban công, cửa sổ, trang trí Giáng sinh"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "California (Mỹ)"], ["Tên khoa học", "Cupressus macrocarpa ''Goldcrest''"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người thích cây có mùi thơm, ban công sáng"]]'::jsonb, '{"mau": ["xanh", "vang"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bền bỉ, trường thọ", "placement": "Ban công, lối vào"}'::jsonb, '["Tùng chanh", "Lemon cypress"]'::jsonb, 'Tùng thơm thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn. Có 2 quy cách.', 'Tùng thơm có tán hình tháp, lá kim mềm màu xanh vàng, vò nhẹ tỏa mùi thơm như chanh. Cây hay được trang trí dịp Giáng sinh, hợp ban công, cửa sổ sáng.'),
('tuyet-tung', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp"], ["Tưới nước", "Tưới khi mặt đất se khô, 1 lần/ngày mùa nắng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–60cm (giống lùn trồng chậu)"], ["Công dụng", "Để bàn sáng, ban công, quà mừng thọ"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người thích cây lá kim dáng tháp"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự trường tồn, bền bỉ với thời gian", "placement": "Ban công, bàn gần cửa sổ"}'::jsonb, '[]'::jsonb, 'Tuyết tùng thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 30–50cm.', 'Tuyết tùng là cây lá kim dáng tháp nhỏ, lá xếp xoắn ốc xanh mướt, hợp trồng chậu để bàn sáng, ban công. Cây sống lâu năm, thường làm quà mừng thọ.'),
('phong-loc-hoa', '[["Ánh sáng", "Ánh sáng tán xạ sáng"], ["Tưới nước", "Tưới vào nõn lá giữ chút nước, đất chỉ cần hơi ẩm; 1–2 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 30–50cm"], ["Công dụng", "Để bàn, phòng khách, quà Tết, khai trương"], ["Cách nhân giống", "Tách chồi con mọc bên gốc"], ["Nguồn gốc", "Châu Mỹ nhiệt đới (họ Dứa)"], ["Sâu bệnh thường gặp", "Thối nõn khi úng nước lâu; rệp sáp"], ["Phù hợp với ai", "Người thích cây có hoa trong nhà"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["sang"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho may mắn, tài lộc", "placement": "Phòng khách, bàn làm việc, gần cửa ra vào"}'::jsonb, '["Dứa cảnh nến", "Dứa cảnh"]'::jsonb, 'Phong lộc hoa thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 30–50cm.', 'Phong lộc hoa (dứa cảnh nến) có lá xếp hình hoa thị, giữa vươn lên cụm hoa màu rực rỡ như ngọn nến, bền màu nhiều tuần. Cây hợp đặt bàn, phòng khách sáng.'),
('huyet-du', '[["Ánh sáng", "Nắng nhẹ đến sáng tán xạ; đủ sáng lá mới đỏ đẹp"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất sáng, viền sân vườn, tiểu cảnh"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Đông Nam Á, Thái Bình Dương"], ["Tên khoa học", "Cordyline fruticosa"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người thích cây lá màu"]]'::jsonb, '{"mau": ["do-hong", "tim"], "anhSang": ["nang-nhe", "sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ tượng trưng cho may mắn, sức sống, xua điều xui", "placement": "Ban công, lối vào, phòng khách sáng"}'::jsonb, '["Phất dụ đỏ", "Ti plant"]'::jsonb, 'Huyết dụ thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–80cm.', 'Huyết dụ có lá dài màu đỏ tía hoặc hồng đậm, mọc thành chùm ở ngọn thân. Cây vừa trồng chậu trong nhà sáng, vừa trồng viền sân vườn, tạo điểm nhấn màu sắc.'),
('hong-phat-tai', '[["Ánh sáng", "Nắng nhẹ đến sáng tán xạ"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50cm–1,5m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, ban công, lối vào"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "New Zealand"], ["Tên khoa học", "Cordyline australis"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người thích cây lá màu, dễ chăm"]]'::jsonb, '{"mau": ["do-hong"], "anhSang": ["nang-nhe", "sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ và tên gọi mang ý nghĩa may mắn, phát tài", "placement": "Phòng khách sáng, ban công, lối vào"}'::jsonb, '["Ánh dương", "Hồng phúc vũ"]'::jsonb, 'Hồng phát tài thuộc nhóm cây văn phòng. Quy cách: Cao 50–80cm.', 'Hồng phát tài có lá dài nhọn màu đỏ tía, mọc tỏa tròn ở ngọn, dáng gọn và nổi bật. Cây dễ thích nghi, trồng được trong nhà sáng lẫn ngoài ban công.'),
('dai-de-vuong', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50–100cm, tán rộng"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí sảnh, phòng khách, văn phòng; quà tặng"], ["Cách nhân giống", "Tách chồi con"], ["Nguồn gốc", "Nam Mỹ (giống lai)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Văn phòng, gia đình muốn cây lá to sang trọng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi và dáng lá uy nghi tượng trưng cho quyền lực, thịnh vượng, thăng tiến", "placement": "Phòng khách, phòng giám đốc, sảnh"}'::jsonb, '["Đế vương", "Philodendron Imperial"]'::jsonb, 'Đại đế vương thuộc nhóm cây văn phòng, cây trong nhà. Quy cách: Cao 50–80cm.', 'Đại đế vương là dạng trầu bà đế vương cỡ lớn, lá to bản, dày, bóng, mọc xòe tạo dáng bề thế. Cây chịu bóng tốt, hợp đặt sảnh, phòng khách rộng.'),
('bang-singapore', '[["Ánh sáng", "Sáng tán xạ mạnh đến nắng nhẹ; thiếu sáng dễ rụng lá"], ["Tưới nước", "Tưới khi đất khô 3–5cm, 1–2 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Trung bình — cần chỗ sáng ổn định"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1–3m trong chậu"], ["An toàn thú cưng", "Không — nhựa trắng gây kích ứng, độc nhẹ với chó mèo"], ["Công dụng", "Cây điểm nhấn phòng khách, sảnh, văn phòng, quán cà phê"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Tây và Trung Phi"], ["Tên khoa học", "Ficus lyrata"], ["Sâu bệnh thường gặp", "Rụng lá khi đổi chỗ, thiếu sáng; đốm nâu khi úng nước"], ["Phù hợp với ai", "Không gian rộng, sáng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "nang-nhe"], "cham": "vua", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá to tượng trưng cho sự sung túc, may mắn, che chở", "placement": "Góc phòng khách sáng, sảnh"}'::jsonb, '["Bàng lá to", "Fiddle leaf fig"]'::jsonb, 'Bàng Singapore thuộc nhóm cây văn phòng, cây trong nhà, cây sân vườn, cây công trình. Có 3 quy cách.', 'Bàng Singapore có lá to hình đàn violin, gân nổi, xanh đậm bóng, dáng cây thẳng sang trọng. Đây là cây điểm nhấn được ưa chuộng ở phòng khách, sảnh, quán cà phê.'),
