('trau-ba-xanh', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn điện"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–3m khi leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột, chậu treo, để kệ, thủy sinh"], ["Cách nhân giống", "Giâm ngọn vào nước hoặc đất, rất dễ ra rễ"], ["Nguồn gốc", "Quần đảo Society (Thái Bình Dương)"], ["Tên khoa học", "Epipremnum aureum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, căn hộ, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự phát triển, may mắn, tiền tài", "placement": "Kệ sách, bàn làm việc, góc phòng khách"}'::jsonb, '["Vạn niên thanh leo", "Pothos", "Hoàng tâm"]'::jsonb, 'Trầu bà xanh thuộc nhóm cây để bàn, cây trong nhà. Có 2 quy cách.', 'Trầu bà xanh có lá hình tim xanh bóng, dây mềm, có thể rủ chậu hoặc leo cột. Cây sống khỏe trong phòng ít sáng, kể cả trồng nước.'),
