('trau-ba-cam-thach', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn điện"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–3m khi leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột, chậu treo, để kệ, thủy sinh"], ["Cách nhân giống", "Giâm ngọn vào nước hoặc đất, rất dễ ra rễ"], ["Nguồn gốc", "Quần đảo Society (Thái Bình Dương)"], ["Tên khoa học", "Epipremnum aureum ''Marble Queen''"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, căn hộ, văn phòng"]]'::jsonb, '{"mau": ["loang", "bac-trang"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự phát triển, may mắn, tiền tài", "placement": "Kệ sách, bàn làm việc, góc phòng khách"}'::jsonb, '["Vạn niên thanh leo", "Pothos", "Hoàng tâm"]'::jsonb, 'Trầu bà cẩm thạch thuộc nhóm cây để bàn, cây trong nhà, cây ban công. Có 3 quy cách.', 'Trầu bà cẩm thạch có lá hình tim loang trắng xanh như vân đá cẩm thạch. Cây dây mềm, hợp chậu treo, kệ, cần chỗ sáng tán xạ để giữ vân trắng.'),
('trau-ba-sua', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn điện"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–3m khi leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột, chậu treo, để kệ, thủy sinh"], ["Cách nhân giống", "Giâm ngọn vào nước hoặc đất, rất dễ ra rễ"], ["Nguồn gốc", "Quần đảo Society (Thái Bình Dương)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, căn hộ, văn phòng"]]'::jsonb, '{"mau": ["bac-trang", "loang"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự phát triển, may mắn, tiền tài", "placement": "Kệ sách, bàn làm việc, góc phòng khách"}'::jsonb, '["Vạn niên thanh leo", "Pothos", "Hoàng tâm"]'::jsonb, 'Trầu bà sữa thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Trầu bà sữa có lá loang trắng sữa xen xanh, nhìn nhẹ nhàng, thanh lịch. Cây dây mềm, hợp để bàn, kệ hoặc chậu treo nơi sáng tán xạ.'),
('hong-mon-mini', '[["Ánh sáng", "Ánh sáng tán xạ sáng; thiếu sáng ít ra hoa"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, phòng khách, quà tặng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Colombia, Ecuador"], ["Tên khoa học", "Anthurium andraeanum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích cây có hoa trong nhà"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ tượng trưng cho tình yêu, may mắn, gia đình đầm ấm", "placement": "Phòng khách, bàn làm việc"}'::jsonb, '["Vĩ hoa tròn", "Anthurium"]'::jsonb, 'Hồng môn mini thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Hồng môn mini là cây hồng môn cỡ nhỏ để bàn, hoa mo đỏ bóng hình trái tim, ra hoa quanh năm khi đủ sáng.'),
('lan-y-mini', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Giữ đất hơi ẩm, tưới 2–3 lần/tuần; lá rũ là dấu hiệu cần tưới"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Trang trí phòng khách, phòng ngủ, văn phòng"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Nguồn gốc", "Trung và Nam Mỹ nhiệt đới"], ["Tên khoa học", "Spathiphyllum wallisii"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh-dam", "co-hoa", "bac-trang"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng tượng trưng cho sự bình yên, thanh khiết, hòa hợp", "placement": "Phòng khách, phòng ngủ, bàn làm việc"}'::jsonb, '["Bạch môn", "Huệ hòa bình", "Peace lily"]'::jsonb, 'Lan ý mini thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Lan ý mini là cây lan ý cỡ nhỏ để bàn, lá xanh bóng, hoa mo trắng thanh khiết. Cây chịu bóng, hợp bàn làm việc, kệ.'),
('ngu-gia-bi-mini', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, ban công, sân vườn; trồng viền"], ["Cách nhân giống", "Giâm cành"], ["Nguồn gốc", "Đài Loan, Hải Nam (Trung Quốc)"], ["Tên khoa học", "Heptapleurum arboricola (syn. Schefflera arboricola)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá xòe như bàn tay tượng trưng cho sự đoàn kết, che chở, gia đình hòa thuận", "placement": "Phòng khách, ban công, góc Đông"}'::jsonb, '["Chân chim", "Schefflera"]'::jsonb, 'Ngũ gia bì mini thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Ngũ gia bì mini là cây ngũ gia bì cỡ nhỏ để bàn, lá xòe như bàn tay, hợp bàn làm việc gần cửa sổ.'),
