('sen-da-do-la', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "10–15cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–20cm"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Mexico, Trung Mỹ, Nam Phi (tùy loài)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá tròn như đồng tiền tượng trưng cho tài lộc", "placement": "Bàn làm việc, quầy thu ngân"}'::jsonb, '["Succulent"]'::jsonb, 'Sen đá đô la thuộc nhóm cây để bàn. Quy cách: Cao 10–15cm.', 'Sen đá đô la có lá tròn dày như đồng xu, được ưa chuộng làm quà tặng mang ý nghĩa tài lộc. Cây cần nắng sáng, ít nước.'),
