('sen-da-kim-cuong', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "10–15cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–20cm"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Mexico, Trung Mỹ, Nam Phi (tùy loài)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tình bạn, tình yêu bền vững", "placement": "Bàn làm việc gần cửa sổ, ban công"}'::jsonb, '["Succulent"]'::jsonb, 'Sen đá kim cương thuộc nhóm cây để bàn. Quy cách: Cao 10–15cm.', 'Sen đá kim cương có lá mọng nước trong như pha lê, ánh lên khi có nắng chiếu. Cây cần nhiều nắng sáng, rất ít nước.'),
('sen-da-mong-rong', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ buổi sáng; chịu bóng hơn các giống sen đá khác"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–20cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Haworthia"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang"], "anhSang": ["sang", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tình bạn, tình yêu bền vững", "placement": "Bàn làm việc gần cửa sổ, ban công"}'::jsonb, '["Haworthia", "Zebra plant"]'::jsonb, 'Sen đá móng rồng thuộc nhóm cây để bàn, cây ban công. Có 2 quy cách.', 'Sen đá móng rồng có lá nhọn dày xếp thành hoa thị, mặt lá có sọc chấm trắng nổi như vảy. Cây chịu bóng hơn các loại sen đá khác, hợp để bàn làm việc.'),
('sen-da-hoa-hong', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–20cm"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Mexico, Trung Mỹ, Nam Phi (tùy loài)"], ["Tên khoa học", "Echeveria và các chi họ Thuốc bỏng (Crassulaceae)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["do-hong", "xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu bền vững", "placement": "Bàn làm việc, cửa sổ"}'::jsonb, '["Succulent"]'::jsonb, 'Sen đá hoa hồng thuộc nhóm cây để bàn, cây ban công. Có 2 quy cách.', 'Sen đá hoa hồng có lá xếp xoắn chặt thành hình bông hồng, mép lá ửng hồng khi đủ nắng. Cây nhỏ xinh, hợp làm quà tặng.'),
('xuong-rong-tai-tho', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ/ngày"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; mùa mưa hạn chế tưới"], ["Đất trồng", "Giá thể cát, sỏi nhỏ, trấu hun, rất thoát nước"], ["Bón phân", "Phân tan chậm liều nhẹ 2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–38°C, chịu nóng tốt, kỵ ẩm ướt kéo dài"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 10–40cm"], ["Công dụng", "Để bàn sáng, cửa sổ, quà tặng"], ["Cách nhân giống", "Tách chồi con, giâm nhánh"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Opuntia microdasys"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Được tin là giúp hóa giải điều xấu, bảo vệ", "placement": "Cửa sổ, ban công"}'::jsonb, '["Bunny ears cactus"]'::jsonb, 'Xương rồng tai thỏ thuộc nhóm cây để bàn, cây ban công. Có 2 quy cách.', 'Xương rồng tai thỏ có các đốt dẹt hình bầu dục mọc đôi như tai thỏ, phủ chấm gai lông mịn. Lưu ý gai lông nhỏ dễ dính tay, nên dùng kẹp khi thay chậu.'),
('xuong-rong-bat-tien', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ/ngày"], ["Tưới nước", "Tưới khi đất se khô, 2 lần/tuần mùa nắng; chịu hạn tốt"], ["Đất trồng", "Giá thể cát, sỏi nhỏ, trấu hun, rất thoát nước"], ["Bón phân", "Phân tan chậm liều nhẹ 2 tháng/lần"], ["Chiều cao", "10–20cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–38°C, chịu nóng tốt, kỵ ẩm ướt kéo dài"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–60cm"], ["An toàn thú cưng", "Không — nhựa trắng độc, gây kích ứng"], ["Công dụng", "Ban công, cửa sổ, hàng rào thấp"], ["Cách nhân giống", "Giâm cành (để khô nhựa trước khi giâm)"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Euphorbia milii"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp"], ["Phù hợp với ai", "Ban công nhiều nắng, người ít thời gian"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa nở quanh năm tượng trưng cho sự bền bỉ, may mắn (tên \"bát tiên\" gắn với tám vị tiên)", "placement": "Ban công, sân trước"}'::jsonb, '["Hoa bát tiên", "Crown of thorns"]'::jsonb, 'Xương rồng bát tiên thuộc nhóm cây để bàn. Quy cách: Cao 10–20cm.', 'Xương rồng bát tiên có thân nhiều gai, lá xanh ở ngọn và hoa đỏ, hồng, vàng nở quanh năm khi đủ nắng. Cây chịu hạn, ít sâu bệnh, hợp ban công, cửa sổ nắng.'),
('xuong-rong-tru', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ/ngày"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; mùa mưa hạn chế tưới"], ["Đất trồng", "Giá thể cát, sỏi nhỏ, trấu hun, rất thoát nước"], ["Bón phân", "Phân tan chậm liều nhẹ 2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–38°C, chịu nóng tốt, kỵ ẩm ướt kéo dài"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 15–60cm, thân trụ đứng"], ["Công dụng", "Để bàn sáng, cửa sổ, quà tặng"], ["Cách nhân giống", "Tách chồi con, giâm nhánh"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Cereus"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Được tin là giúp hóa giải điều xấu, bảo vệ", "placement": "Cửa sổ, ban công"}'::jsonb, '["Cactus"]'::jsonb, 'Xương rồng trụ thuộc nhóm cây để bàn, cây ban công. Có 2 quy cách.', 'Xương rồng trụ có thân hình trụ đứng thẳng, có khía dọc và hàng gai đều, dáng hiện đại. Cây rất chịu hạn, cần nhiều nắng.'),
('xuong-rong-cau', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ/ngày"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; mùa mưa hạn chế tưới"], ["Đất trồng", "Giá thể cát, sỏi nhỏ, trấu hun, rất thoát nước"], ["Bón phân", "Phân tan chậm liều nhẹ 2 tháng/lần"], ["Chiều cao", "10–15cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–38°C, chịu nóng tốt, kỵ ẩm ướt kéo dài"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 5–15cm, thân tròn"], ["Công dụng", "Để bàn sáng, cửa sổ, quà tặng"], ["Cách nhân giống", "Tách chồi con, giâm nhánh"], ["Nguồn gốc", "Châu Mỹ"], ["Tên khoa học", "Họ Xương rồng (Cactaceae), dạng cầu"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Được tin là giúp hóa giải điều xấu, bảo vệ", "placement": "Cửa sổ, ban công"}'::jsonb, '["Cactus"]'::jsonb, 'Xương rồng cầu thuộc nhóm cây để bàn. Quy cách: Cao 10–15cm.', 'Xương rồng cầu có thân tròn như quả bóng, khía múi và hàng gai đều, một số giống ra hoa trên đỉnh. Cây nhỏ gọn, rất dễ chăm.'),
('nha-dam-mini', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "15–25cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["An toàn thú cưng", "Không — độc với chó mèo nếu ăn phải"], ["Công dụng", "Trang trí ban công, cửa sổ, bàn sáng"], ["Cách nhân giống", "Tách cây con mọc quanh gốc"], ["Nguồn gốc", "Bán đảo Ả Rập"], ["Tên khoa học", "Aloe vera"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, ban công nắng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sức khỏe, sự bảo vệ", "placement": "Ban công, cửa sổ, bếp sáng"}'::jsonb, '["Lô hội", "Aloe vera"]'::jsonb, 'Nha đam mini thuộc nhóm cây để bàn. Quy cách: Cao 15–25cm.', 'Nha đam mini là cây nha đam cỡ nhỏ để bàn, lá mọng nước, chịu hạn, cần chỗ có nắng sáng như cửa sổ, bàn gần ban công.'),
('duong-xi-mini', '[["Ánh sáng", "Ánh sáng tán xạ, bóng râm; tránh nắng gắt"], ["Tưới nước", "Giữ đất luôn ẩm, tưới 1 lần/ngày mùa khô; phun sương lên lá"], ["Đất trồng", "Đất giàu mùn, xơ dừa, giữ ẩm tốt"], ["Bón phân", "Phân hữu cơ hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–30°C, ưa ẩm cao"], ["Mức độ dễ chăm", "Trung bình — không để khô đất"], ["Tốc độ sinh trưởng", "Nhanh"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Giỏ treo, chậu treo hiên, ban công, kệ cao"], ["Cách nhân giống", "Tách bụi"], ["Nguồn gốc", "Vùng nhiệt đới châu Mỹ"], ["Tên khoa học", "Nephrolepis exaltata"], ["Sâu bệnh thường gặp", "Khô, rụng lá khi thiếu ẩm; rệp sáp"], ["Phù hợp với ai", "Ban công, hiên có bóng mát"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bình yên, che chở", "placement": "Hiên nhà, ban công, cửa sổ"}'::jsonb, '["Dương xỉ lá kiếm", "Boston fern"]'::jsonb, 'Dương xỉ mini thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Dương xỉ mini là cây dương xỉ cỡ nhỏ, lá mềm xanh mướt, hợp để bàn, kệ nơi mát và ẩm.'),
('chuoi-ngoc', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "Không — quả và lá độc với chó mèo"], ["Công dụng", "Hàng rào, cây tạo hình, viền lối đi"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Châu Mỹ nhiệt đới"], ["Tên khoa học", "Duranta erecta"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Sân vườn, công trình cảnh quan"]]'::jsonb, '{"mau": ["tim", "vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc", "chiuGio": true}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho sự sung túc, quý giá", "placement": "Hàng rào, sân trước"}'::jsonb, '["Thanh quan", "Chuỗi ngọc bụi", "Golden dewdrop"]'::jsonb, 'Chuỗi ngọc thuộc nhóm cây để bàn, cây ban công, cây sân vườn, cây công trình. Có 4 quy cách.', 'Chuỗi ngọc (thanh quan) là cây bụi, hoa tím nhỏ thành chùm rủ và quả vàng như chuỗi ngọc; giống lá vàng được trồng nhiều làm hàng rào. Cây chịu nắng, dễ cắt tỉa tạo hình.'),
('chuoi-hat', '[["Ánh sáng", "Nắng sáng 4–6 giờ/ngày; thiếu nắng cây vươn dài, nhạt màu"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Dây rủ dài 30–60cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo"], ["Công dụng", "Để bàn sáng, cửa sổ, ban công, quà tặng"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Curio herreianus (syn. Senecio herreianus)"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người mới trồng cây, học sinh, sinh viên"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tình bạn, tình yêu bền vững", "placement": "Bàn làm việc gần cửa sổ, ban công"}'::jsonb, '["Sen đá chuỗi hạt", "String of beads"]'::jsonb, 'Chuỗi hạt thuộc nhóm cây để bàn, cây ban công. Có 2 quy cách.', 'Chuỗi hạt là cây mọng nước dạng dây, lá như những hạt nhỏ hình bầu dục xâu thành chuỗi rủ xuống. Cây hợp chậu treo cửa sổ, kệ cao có nắng sáng.'),
('phat-tai-mini', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "25–35cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh; quà khai trương"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng muốn cây cao dễ chăm"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa phát tài phát lộc, làm ăn thuận lợi", "placement": "Phòng khách, phòng làm việc, góc Đông Nam"}'::jsonb, '["Thiết mộc lan", "Corn plant"]'::jsonb, 'Phát tài mini thuộc nhóm cây để bàn. Quy cách: Cao 25–35cm.', 'Phát tài mini là cây phát tài cỡ nhỏ để bàn, lá xanh bóng mọc thành chùm. Cây chịu bóng, chịu máy lạnh, rất hợp bàn làm việc.'),
('thiet-moc-lan-mini', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "25–35cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí phòng khách, văn phòng, sảnh; quà khai trương"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans ''Massangeana''"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Gia đình, văn phòng muốn cây cao dễ chăm"]]'::jsonb, '{"mau": ["loang", "vang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi mang ý nghĩa phát tài phát lộc, làm ăn thuận lợi", "placement": "Phòng khách, phòng làm việc, góc Đông Nam"}'::jsonb, '["Phát tài", "Mass cane"]'::jsonb, 'Thiết mộc lan mini thuộc nhóm cây để bàn. Quy cách: Cao 25–35cm.', 'Thiết mộc lan mini là cây phát tài sọc vàng cỡ nhỏ, hợp đặt bàn làm việc, kệ. Cây chịu bóng, ít phải tưới.'),
('huyet-du-mini', '[["Ánh sáng", "Nắng nhẹ đến sáng tán xạ; đủ sáng lá mới đỏ đẹp"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "25–35cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất sáng, viền sân vườn, tiểu cảnh"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Đông Nam Á, Thái Bình Dương"], ["Tên khoa học", "Cordyline fruticosa"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người thích cây lá màu"]]'::jsonb, '{"mau": ["do-hong", "tim"], "anhSang": ["nang-nhe", "sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc đỏ tượng trưng cho may mắn, sức sống, xua điều xui", "placement": "Ban công, lối vào, phòng khách sáng"}'::jsonb, '["Phất dụ đỏ", "Ti plant"]'::jsonb, 'Huyết dụ mini thuộc nhóm cây để bàn. Quy cách: Cao 25–35cm.', 'Huyết dụ mini là cây huyết dụ cỡ nhỏ, lá đỏ tía nổi bật, hợp đặt bàn làm việc gần cửa sổ, kệ sáng.'),
('truc-phu-quy', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Trồng nước thì thay nước 7–10 ngày/lần; trồng đất tưới khi mặt đất se khô"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 20–60cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Để bàn, kệ, bàn thờ thần tài, quà tặng"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Trung Phi"], ["Tên khoa học", "Dracaena sanderiana"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho phú quý, may mắn, sự bền bỉ", "placement": "Bàn làm việc, quầy thu ngân, bàn thờ thần tài"}'::jsonb, '["Phát lộc", "Trúc may mắn", "Lucky bamboo"]'::jsonb, 'Trúc phú quý thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Trúc phú quý là cây phát lộc thân xanh chia đốt như trúc, lá thon dài, có thể trồng đất hoặc cắm nước. Cây rất dễ sống trong nhà, hợp để bàn, bàn thờ thần tài.'),
('phat-du', '[["Ánh sáng", "Sáng tán xạ đến nắng nhẹ buổi sáng; chịu được bóng râm trong nhà"], ["Tưới nước", "Tưới khi đất khô 3–4cm, khoảng 1–2 lần/tuần; cây chịu hạn hơn chịu úng"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 30–150cm tùy giống"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Để bàn, kệ, trang trí nội thất"], ["Cách nhân giống", "Giâm khúc thân, giâm ngọn"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, văn phòng"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Được xem là cây mang lại may mắn, bình an", "placement": "Bàn làm việc, kệ"}'::jsonb, '[]'::jsonb, 'Phất dụ thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm.', 'Phất dụ là nhóm cây thuộc chi Dracaena, lá dài thuôn, nhiều giống có sọc vàng hoặc trắng. Cây chịu bóng, dễ sống, hợp đặt bàn, kệ hoặc góc nhà.'),
('thuy-sinh-kim-tien', '[["Ánh sáng", "Ánh sáng tán xạ trong nhà; không đặt dưới nắng gắt (nước nóng, rêu mọc)"], ["Tưới nước", "Giữ mực nước ngập rễ, không ngập thân; thay nước 7–10 ngày/lần"], ["Đất trồng", "Trồng nước (thủy canh), có thể thêm sỏi giữ gốc"], ["Bón phân", "Vài giọt dung dịch thủy canh mỗi lần thay nước"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["An toàn thú cưng", "Không — độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, quầy lễ tân, quà tặng"], ["Cách nhân giống", "Giâm ngọn vào nước"], ["Nguồn gốc", "Đông Phi"], ["Tên khoa học", "Zamioculcas zamiifolia"], ["Sâu bệnh thường gặp", "Thối rễ khi nước bẩn lâu ngày; rêu bám bình"], ["Phù hợp với ai", "Văn phòng, người không muốn dùng đất"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho tiền tài, phú quý", "placement": "Bàn làm việc, quầy thu ngân"}'::jsonb, '[]'::jsonb, 'Thủy sinh kim tiền thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm, kèm bình thủy tinh.', 'Kim tiền thủy sinh được trồng trong bình thủy tinh, nhìn thấy rễ trắng sạch sẽ, không bám đất. Cây gọn đẹp, hợp để bàn làm việc, quầy lễ tân.'),
('thuy-sinh-phat-tai', '[["Ánh sáng", "Ánh sáng tán xạ trong nhà; không đặt dưới nắng gắt (nước nóng, rêu mọc)"], ["Tưới nước", "Giữ mực nước ngập rễ, không ngập thân; thay nước 7–10 ngày/lần"], ["Đất trồng", "Trồng nước (thủy canh), có thể thêm sỏi giữ gốc"], ["Bón phân", "Vài giọt dung dịch thủy canh mỗi lần thay nước"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo"], ["Công dụng", "Để bàn, kệ, quà tặng"], ["Cách nhân giống", "Giâm ngọn vào nước"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Dracaena fragrans"], ["Sâu bệnh thường gặp", "Thối rễ khi nước bẩn lâu ngày; rêu bám bình"], ["Phù hợp với ai", "Văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho phát tài phát lộc", "placement": "Bàn làm việc, quầy thu ngân"}'::jsonb, '[]'::jsonb, 'Thủy sinh phát tài thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm, kèm bình thủy tinh.', 'Phát tài thủy sinh được trồng trong bình thủy tinh, rễ trắng, thân lá xanh bóng. Cây sạch sẽ, dễ chăm, hợp để bàn, kệ.'),
