('thuy-sinh-van-loc', '[["Ánh sáng", "Ánh sáng tán xạ trong nhà; không đặt dưới nắng gắt (nước nóng, rêu mọc)"], ["Tưới nước", "Giữ mực nước ngập rễ, không ngập thân; thay nước 7–10 ngày/lần"], ["Đất trồng", "Trồng nước (thủy canh), có thể thêm sỏi giữ gốc"], ["Bón phân", "Vài giọt dung dịch thủy canh mỗi lần thay nước"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["An toàn thú cưng", "Không — độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Để bàn, quà tặng"], ["Cách nhân giống", "Giâm ngọn vào nước"], ["Nguồn gốc", "Đông Nam Á (giống lai)"], ["Tên khoa học", "Aglaonema (giống lai, nhóm Rotundum)"], ["Sâu bệnh thường gặp", "Thối rễ khi nước bẩn lâu ngày; rêu bám bình"], ["Phù hợp với ai", "Văn phòng"]]'::jsonb, '{"mau": ["do-hong"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho vạn sự may mắn, tài lộc", "placement": "Bàn làm việc, quầy thu ngân"}'::jsonb, '[]'::jsonb, 'Thủy sinh vạn lộc thuộc nhóm cây để bàn. Quy cách: Cao 20–30cm, kèm bình thủy tinh.', 'Vạn lộc thủy sinh trồng trong bình thủy tinh, lá hồng đỏ xen xanh nổi bật, rễ trắng. Cây sạch, dễ chăm, hợp để bàn.'),
('monstera-deliciosa', '[["Ánh sáng", "Ánh sáng tán xạ sáng; chịu bóng nhưng lá ít xẻ hơn"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 1–2m trong chậu (cần cột cho leo)"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Cây điểm nhấn phòng khách, quán cà phê, văn phòng"], ["Cách nhân giống", "Giâm đốt thân có rễ khí"], ["Nguồn gốc", "Trung Mỹ (Mexico đến Panama)"], ["Tên khoa học", "Monstera deliciosa"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích phong cách nhiệt đới, không gian rộng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá to xòe rộng tượng trưng cho sự phát triển, sung túc", "placement": "Góc phòng khách sáng, sảnh"}'::jsonb, '["Trầu bà Nam Mỹ", "Swiss cheese plant"]'::jsonb, 'Monstera deliciosa thuộc nhóm cây trong nhà. Quy cách: Cao 80–120cm.', 'Monstera deliciosa là giống monstera lá to, xẻ thùy và thủng lỗ đặc trưng; cây trưởng thành cần cột cho leo. Cây hợp làm điểm nhấn góc phòng khách, sảnh, quán cà phê.'),
('monstera-adansonii', '[["Ánh sáng", "Ánh sáng tán xạ sáng; chịu bóng nhưng lá ít xẻ hơn"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "40–60cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–2m, leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Cây điểm nhấn phòng khách, quán cà phê, văn phòng"], ["Cách nhân giống", "Giâm đốt thân có rễ khí"], ["Nguồn gốc", "Trung và Nam Mỹ"], ["Tên khoa học", "Monstera adansonii"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người thích phong cách nhiệt đới, không gian rộng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá to xòe rộng tượng trưng cho sự phát triển, sung túc", "placement": "Góc phòng khách sáng, sảnh"}'::jsonb, '["Trầu bà lá thủng", "Swiss cheese vine"]'::jsonb, 'Monstera adansonii thuộc nhóm cây trong nhà. Quy cách: Cao 40–60cm.', 'Monstera adansonii là cây dây leo lá nhỏ, nhiều lỗ thủng như ren, có thể leo cột hoặc trồng chậu treo cho rủ. Cây lớn nhanh, chịu bóng, hợp kệ sách, cửa sổ.'),
('luoi-ho-bac', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ; chịu bóng râm, đèn văn phòng"], ["Tưới nước", "Tưới khi đất khô hẳn, 1 lần/7–10 ngày; lá mọng nước, rất chịu hạn"], ["Đất trồng", "Đất thịt nhẹ trộn xơ dừa, trấu hun, thoát nước tốt"], ["Bón phân", "Phân tan chậm 2 tháng/lần hoặc NPK pha loãng 1 lần/tháng"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C; tránh lạnh dưới 12°C"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 50–120cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (saponin) nếu ăn phải"], ["Công dụng", "Trang trí nội thất, đặt phòng ngủ, văn phòng, lối vào"], ["Cách nhân giống", "Tách bụi, giâm lá"], ["Nguồn gốc", "Tây Phi nhiệt đới"], ["Tên khoa học", "Dracaena trifasciata ''Moonshine''"], ["Sâu bệnh thường gặp", "Thối gốc khi tưới nhiều, cháy chóp lá khi nước nhiều clo hoặc thiếu ẩm, rệp sáp"], ["Phù hợp với ai", "Người mới trồng cây, hay đi công tác, ít thời gian"]]'::jsonb, '{"mau": ["bac-trang"], "anhSang": ["sang", "ram", "den", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Sắc bạc mang ý nghĩa thanh lọc, bình an; lá mọc thẳng tượng trưng sự vững vàng", "placement": "Phòng khách, phòng ngủ, bàn làm việc"}'::jsonb, '["Hổ vĩ", "Snake plant", "Sansevieria"]'::jsonb, 'Lưỡi hổ bạc thuộc nhóm cây trong nhà. Quy cách: Cao 50–80cm.', 'Lưỡi hổ bạc có lá màu xanh bạc ánh trắng, dáng gọn và sang. Cây dễ sống như các giống lưỡi hổ khác, chịu hạn và thiếu sáng tốt.'),
('van-nien-thanh-leo', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm tốt; tránh nắng gắt chiếu thẳng làm cháy lá"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Chiều cao", "60–100cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 60cm–1,5m (leo cột)"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột trang trí góc phòng, sảnh"], ["Cách nhân giống", "Tách bụi, giâm thân hoặc ngọn"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Gia đình, văn phòng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "ram"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vươn lên, phát triển", "placement": "Góc phòng khách, sảnh"}'::jsonb, '["Trầu bà leo cột"]'::jsonb, 'Vạn niên thanh leo thuộc nhóm cây trong nhà. Quy cách: Cao 60–100cm.', 'Vạn niên thanh leo là cây dây leo họ Ráy được trồng leo cột, lá xanh bóng mọc dày quanh trụ. Cây chịu bóng, lớn nhanh, hợp đặt góc phòng, sảnh.'),
('dua-can', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi mặt đất se khô; chịu hạn tốt, kỵ úng"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–50cm"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Chậu ban công, bồn hoa, viền lối đi"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Catharanthus roseus"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nhiều nắng, người mới trồng hoa"]]'::jsonb, '{"mau": ["do-hong", "co-hoa", "bac-trang"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa nở quanh năm tượng trưng cho sức sống bền bỉ", "placement": "Ban công, sân trước"}'::jsonb, '["Hải đằng", "Bông dừa", "Periwinkle"]'::jsonb, 'Dừa cạn thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Dừa cạn có hoa 5 cánh màu hồng, trắng, tím nở quanh năm, lá xanh bóng. Cây chịu nắng nóng, chịu hạn, rất hợp chậu ban công, bồn hoa.'),
('muoi-gio', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; lá mọng nên chịu hạn tốt"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "15–25cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–20cm, bò lan"], ["An toàn thú cưng", "Không — độc với mèo"], ["Công dụng", "Chậu ban công, bồn viền, chậu treo"], ["Cách nhân giống", "Giâm cành, rất dễ ra rễ"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Portulaca grandiflora"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nhiều nắng, người mới trồng hoa"]]'::jsonb, '{"mau": ["do-hong", "vang", "tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự tươi vui, may mắn", "placement": "Ban công, sân thượng"}'::jsonb, '["Hoa mười giờ", "Moss rose"]'::jsonb, 'Mười giờ thuộc nhóm cây ban công. Quy cách: Cao 15–25cm.', 'Mười giờ là cây thân thảo mọng nước, hoa nhiều màu nở rộ vào buổi sáng nắng. Cây cực kỳ dễ trồng, chịu nắng nóng, hợp chậu ban công, bồn viền.'),
('muoi-gio-thai', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; lá mọng nên chịu hạn tốt"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "15–25cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–20cm, bò lan"], ["An toàn thú cưng", "Không — độc với mèo"], ["Công dụng", "Chậu ban công, bồn viền, chậu treo"], ["Cách nhân giống", "Giâm cành, rất dễ ra rễ"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Portulaca (giống lai Thái Lan)"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nhiều nắng, người mới trồng hoa"]]'::jsonb, '{"mau": ["do-hong", "vang", "tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự tươi vui, may mắn", "placement": "Ban công, sân thượng"}'::jsonb, '["Hoa mười giờ", "Moss rose"]'::jsonb, 'Mười giờ Thái thuộc nhóm cây ban công. Quy cách: Cao 15–25cm.', 'Mười giờ Thái là giống mười giờ lai, hoa to, cánh kép nhiều màu, nở lâu hơn giống thường. Cây chịu nắng, dễ giâm cành, hợp chậu treo, ban công.'),
('su-quan-tu', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng nhẹ; đủ nắng mới ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giảm khi trời mưa"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 3–8m"], ["Công dụng", "Leo giàn, cổng, hàng rào, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Combretum indicum (syn. Quisqualis indica)"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Nhà có giàn, ban công rộng"]]'::jsonb, '{"mau": ["do-hong", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tên gọi gắn với người quân tử; hoa đổi màu tượng trưng cho sự thăng tiến", "placement": "Cổng, ban công, sân thượng"}'::jsonb, '["Dây giun", "Rangoon creeper"]'::jsonb, 'Sử quân tử thuộc nhóm cây ban công, cây sân vườn. Có 2 quy cách.', 'Sử quân tử là cây dây leo, hoa mọc thành chùm rủ, nở trắng rồi chuyển hồng, đỏ, thơm về đêm. Cây lớn nhanh, chịu nắng, hợp leo giàn, cổng, ban công.'),
('hoa-tigon', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng nhẹ; đủ nắng mới ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giảm khi trời mưa"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 3–6m"], ["Công dụng", "Leo giàn, hàng rào, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Antigonon leptopus"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Nhà có giàn, ban công rộng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu lãng mạn", "placement": "Giàn, cổng, ban công"}'::jsonb, '["Coral vine"]'::jsonb, 'Hoa tigon thuộc nhóm cây ban công. Quy cách: Dây dài 80–120cm.', 'Ti gôn là cây dây leo lá hình tim, hoa nhỏ màu hồng phấn mọc thành chùm dày. Cây lớn rất nhanh, chịu nắng, hợp leo giàn, hàng rào, ban công.'),
('hoa-giay-thai', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ, càng nắng càng nhiều hoa"], ["Tưới nước", "Tưới khi đất khô; hơi hạn mới ra nhiều hoa, kỵ úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m, có thể leo giàn"], ["An toàn thú cưng", "Thân có gai, nhựa có thể gây kích ứng nhẹ"], ["Công dụng", "Leo cổng, giàn, ban công, bonsai, hàng rào"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Bougainvillea (giống Thái Lan)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Nhà có sân, ban công nhiều nắng"]]'::jsonb, '{"mau": ["do-hong", "tim", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu bền bỉ, sự may mắn, hưng thịnh", "placement": "Cổng, ban công, sân trước"}'::jsonb, '["Bông giấy", "Bougainvillea"]'::jsonb, 'Hoa giấy Thái thuộc nhóm cây ban công. Quy cách: Cao 80–120cm.', 'Hoa giấy Thái là giống hoa giấy lai, hoa to, màu đậm, ra hoa nhiều và lâu hơn giống thường. Cây chịu nắng, hợp chậu ban công, tạo dáng.'),
('hoa-hong', '[["Ánh sáng", "Nắng trực tiếp ít nhất 5–6 giờ/ngày"], ["Tưới nước", "Tưới gốc 1 lần/ngày sáng sớm, không tưới lên lá để tránh nấm"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ + NPK giàu lân, kali 1–2 tuần/lần; cắt bỏ hoa tàn"], ["Chiều cao", "40–70cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Trung bình — cần bón phân, phòng nấm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 40–80cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc); lưu ý gai"], ["Công dụng", "Chậu ban công, sân vườn, cắm hoa"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Châu Á, châu Âu (giống lai)"], ["Tên khoa học", "Rosa"], ["Sâu bệnh thường gặp", "Đốm đen, phấn trắng, rệp, nhện đỏ, sâu xanh"], ["Phù hợp với ai", "Người yêu hoa, có thời gian chăm"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu, sự lãng mạn", "placement": "Ban công, sân trước"}'::jsonb, '["Hồng", "Rose"]'::jsonb, 'Hoa hồng thuộc nhóm cây ban công. Quy cách: Cao 40–70cm.', 'Hoa hồng có hoa to, cánh kép, nhiều màu và hương thơm, là loài hoa được yêu thích nhất. Cây cần nhiều nắng, bón phân đều và phòng nấm để ra hoa đẹp.'),
('hoa-hong-leo', '[["Ánh sáng", "Nắng trực tiếp ít nhất 5–6 giờ/ngày"], ["Tưới nước", "Tưới gốc 1 lần/ngày sáng sớm, không tưới lên lá để tránh nấm"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ + NPK giàu lân, kali 1–2 tuần/lần; cắt bỏ hoa tàn"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Trung bình — cần bón phân, phòng nấm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 1–3m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc); lưu ý gai"], ["Công dụng", "Chậu ban công, sân vườn, cắm hoa"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Châu Á, châu Âu (giống lai)"], ["Tên khoa học", "Rosa"], ["Sâu bệnh thường gặp", "Đốm đen, phấn trắng, rệp, nhện đỏ, sâu xanh"], ["Phù hợp với ai", "Người yêu hoa, có thời gian chăm"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "vua", "thuCung": "an-toan"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu, sự lãng mạn", "placement": "Ban công, sân trước"}'::jsonb, '["Hồng", "Rose"]'::jsonb, 'Hoa hồng leo thuộc nhóm cây ban công. Quy cách: Dây dài 60–100cm.', 'Hoa hồng leo có thân dài mềm, cho leo cổng, giàn, lan can, ra hoa thành chùm nhiều màu. Cây cần nhiều nắng, giàn chắc và bón phân đều.'),
('hoa-dua-can-ru', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi mặt đất se khô; chịu hạn tốt, kỵ úng"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây rủ 30–50cm"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Chậu ban công, bồn hoa, viền lối đi"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Catharanthus roseus"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nhiều nắng, người mới trồng hoa"]]'::jsonb, '{"mau": ["do-hong", "co-hoa", "bac-trang"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa nở quanh năm tượng trưng cho sức sống bền bỉ", "placement": "Ban công, sân trước"}'::jsonb, '["Hải đằng", "Bông dừa", "Periwinkle"]'::jsonb, 'Hoa dừa cạn rủ thuộc nhóm cây ban công. Quy cách: Dây dài 30–50cm.', 'Dừa cạn rủ là giống dừa cạn thân bò, cành rủ mềm phủ đầy hoa, rất hợp chậu treo, lan can. Cây chịu nắng nóng, ra hoa quanh năm.'),
('hoa-da-yen-thao', '[["Ánh sáng", "Nắng nhẹ buổi sáng 4–6 giờ; tránh nắng gắt và mưa dầm làm dập hoa"], ["Tưới nước", "Tưới 1 lần/ngày vào sáng sớm hoặc chiều mát mùa nắng; tưới gốc, tránh tưới lên hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Ưa mát 18–30°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây rủ 30–50cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Chậu treo ban công, cửa sổ, lan can"], ["Cách nhân giống", "Gieo hạt, giâm ngọn"], ["Nguồn gốc", "Nam Mỹ (giống lai)"], ["Tên khoa học", "Petunia × hybrida"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nắng sáng"]]'::jsonb, '{"mau": ["tim", "do-hong", "bac-trang", "co-hoa"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự lãng mạn, niềm vui", "placement": "Ban công, cửa sổ"}'::jsonb, '["Petunia"]'::jsonb, 'Hoa dạ yến thảo thuộc nhóm cây ban công. Quy cách: Dây dài 30–50cm.', 'Dạ yến thảo có hoa hình phễu nhiều màu, giống rủ cho thác hoa rất đẹp khi treo. Cây ưa nắng nhẹ, khí hậu mát, hợp chậu treo ban công, cửa sổ.'),
('hoa-ngoc-thao', '[["Ánh sáng", "Ánh sáng tán xạ hoặc nắng nhẹ buổi sáng; chịu bóng hơn các loại hoa khác"], ["Tưới nước", "Giữ đất ẩm đều, tưới 1 lần/ngày; thân mọng dễ héo khi khô"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 20–30cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Chậu ban công, hiên nhà, bồn viền"], ["Cách nhân giống", "Giâm ngọn, gieo hạt"], ["Nguồn gốc", "Đông Phi"], ["Tên khoa học", "Impatiens walleriana"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công ít nắng"]]'::jsonb, '{"mau": ["do-hong", "bac-trang", "co-hoa"], "anhSang": ["nang-nhe", "sang"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho niềm vui, sự tươi mới", "placement": "Ban công, hiên nhà"}'::jsonb, '["Hoa mai địa thảo", "Busy Lizzie"]'::jsonb, 'Hoa ngọc thảo thuộc nhóm cây ban công. Quy cách: Cao 20–30cm.', 'Ngọc thảo có thân mọng, hoa 5 cánh nhiều màu nở dày phủ kín tán. Cây chịu bóng hơn nhiều loại hoa khác, hợp chậu ban công ít nắng, hiên nhà.'),
('hoa-cuc', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày vào sáng sớm hoặc chiều mát mùa nắng; tưới gốc, tránh tưới lên hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–50cm"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Chậu ban công, chưng Tết, bồn hoa"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Đông Á"], ["Tên khoa học", "Chrysanthemum × morifolium"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người thích hoa truyền thống"]]'::jsonb, '{"mau": ["vang", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho sự trường thọ, thanh cao", "placement": "Ban công, phòng khách dịp Tết"}'::jsonb, '["Cúc", "Chrysanthemum"]'::jsonb, 'Hoa cúc thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Hoa cúc có nhiều màu vàng, trắng, tím, đỏ, nở thành khóm tròn đẹp. Cây ưa nắng, thường chưng Tết, trang trí ban công.'),
('cuc-mat-troi', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày vào sáng sớm hoặc chiều mát mùa nắng; tưới gốc, tránh tưới lên hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–50cm"], ["Công dụng", "Chậu ban công, chưng Tết, bồn hoa"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Đông Á"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người thích hoa truyền thống"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho sự trường thọ, thanh cao", "placement": "Ban công, phòng khách dịp Tết"}'::jsonb, '["Cúc", "Chrysanthemum"]'::jsonb, 'Cúc mặt trời thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Cúc mặt trời có hoa màu vàng cam rực rỡ như những mặt trời nhỏ, nở nhiều trong mùa nắng. Cây dễ trồng, hợp chậu ban công, bồn hoa.'),
('cuc-la-nham', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày vào sáng sớm hoặc chiều mát mùa nắng; tưới gốc, tránh tưới lên hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–50cm"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Chậu ban công, chưng Tết, bồn hoa"], ["Cách nhân giống", "Gieo hạt"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Zinnia elegans"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người thích hoa truyền thống"]]'::jsonb, '{"mau": ["do-hong", "vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho sự trường thọ, thanh cao", "placement": "Ban công, phòng khách dịp Tết"}'::jsonb, '["Cúc ngũ sắc", "Zinnia"]'::jsonb, 'Cúc lá nhám thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Cúc lá nhám (cúc zinnia) có hoa to nhiều màu tươi, lá hơi nhám, nở liên tục trong mùa nắng. Cây lớn nhanh, dễ gieo hạt, hợp bồn hoa, chậu ban công.'),
('song-doi', '[["Ánh sáng", "Nắng nhẹ đến nắng sáng; đủ sáng mới ra hoa"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "20–30cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 20–30cm"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Để bàn sáng, ban công, chưng Tết, mừng thọ"], ["Cách nhân giống", "Giâm lá, tách cây con"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Kalanchoe blossfeldiana"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Người thích cây hoa nhỏ dễ chăm"]]'::jsonb, '{"mau": ["do-hong", "vang", "co-hoa"], "anhSang": ["nang-nhe", "sang"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tên gọi mang ý nghĩa sống lâu, trường thọ", "placement": "Ban công, cửa sổ, phòng khách sáng"}'::jsonb, '["Trường thọ", "Kalanchoe"]'::jsonb, 'Sống đời thuộc nhóm cây ban công. Quy cách: Cao 20–30cm.', 'Sống đời có lá dày mọng nước, ra những chùm hoa nhỏ đỏ, cam, vàng, hồng nở rộ và bền nhiều tuần. Cây thường dùng chưng Tết, tặng mừng thọ.'),
('thach-thao', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày vào sáng sớm hoặc chiều mát mùa nắng; tưới gốc, tránh tưới lên hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–50cm"], ["Công dụng", "Chậu ban công, bồn hoa"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người thích hoa nhỏ màu tím"]]'::jsonb, '{"mau": ["tim", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho tình yêu chân thành, sự nhớ nhung", "placement": "Ban công"}'::jsonb, '[]'::jsonb, 'Thạch thảo thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Thạch thảo có những bông hoa nhỏ màu tím nở thành chùm dày, gợi cảm giác dịu dàng, mộc mạc. Cây ưa nắng, hợp chậu ban công, bồn hoa.'),
('oai-huong', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ"], ["Tưới nước", "Tưới khi đất khô, 2–3 lần/tuần; rất kỵ úng"], ["Đất trồng", "Đất cát pha, thoát nước rất tốt, hơi kiềm"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Ưa mát, khô; nắng nóng ẩm miền Nam cây nhanh tàn"], ["Mức độ dễ chăm", "Khó — cần nắng, thoáng, ít nước"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 30–60cm"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo nếu ăn nhiều"], ["Công dụng", "Chậu ban công nắng, cửa sổ, trang trí"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Địa Trung Hải"], ["Tên khoa học", "Lavandula angustifolia"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người có kinh nghiệm trồng cây, ban công nhiều nắng"]]'::jsonb, '{"mau": ["tim", "co-hoa"], "anhSang": ["nang-gat"], "cham": "kho", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự thủy chung, thanh thản", "placement": "Ban công, cửa sổ phòng ngủ"}'::jsonb, '["Lavender"]'::jsonb, 'Oải hương thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Oải hương có lá bạc thơm và cành hoa tím mảnh, tỏa mùi thơm dịu đặc trưng. Cây ưa khí hậu mát khô; ở miền Nam cần chỗ thật nắng, thoáng và tưới ít.'),
('ngu-sac', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới khi đất se khô; chịu hạn tốt"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "30–50cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 30cm–1m"], ["An toàn thú cưng", "Không — độc với chó mèo (đặc biệt quả)"], ["Công dụng", "Chậu ban công, bồn hoa, hàng rào thấp"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Trung và Nam Mỹ"], ["Tên khoa học", "Lantana camara"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công nắng gió, người ít thời gian"]]'::jsonb, '{"mau": ["vang", "do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa nhiều màu tượng trưng cho sự sung túc, may mắn", "placement": "Ban công, sân trước"}'::jsonb, '["Thơm ổi", "Trâm ổi", "Lantana"]'::jsonb, 'Ngũ sắc thuộc nhóm cây ban công. Quy cách: Cao 30–50cm.', 'Ngũ sắc có những chùm hoa nhỏ đổi màu từ vàng sang cam, đỏ, hồng trên cùng một chùm. Cây chịu nắng nóng, chịu hạn, ra hoa quanh năm, thu hút bướm.'),
('trang-thai', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "40–60cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 30–80cm"], ["Công dụng", "Chậu ban công, bồn viền, hàng rào thấp, cúng lễ"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Ixora (giống lùn Thái Lan)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công nắng, sân vườn"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa đỏ tượng trưng cho may mắn, thường dùng cúng lễ", "placement": "Ban công, sân trước"}'::jsonb, '["Ixora"]'::jsonb, 'Trang thái thuộc nhóm cây ban công. Quy cách: Cao 40–60cm.', 'Trang Thái là giống trang lùn, lá nhỏ, tán gọn, ra những chùm hoa tròn đỏ cam dày đặc quanh năm. Cây chịu nắng, hợp chậu ban công, bồn viền, hàng rào thấp.'),
('trang-do', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 30–80cm"], ["Công dụng", "Chậu ban công, bồn viền, hàng rào thấp, cúng lễ"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Ixora coccinea"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công nắng, sân vườn"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa đỏ tượng trưng cho may mắn, thường dùng cúng lễ", "placement": "Ban công, sân trước"}'::jsonb, '["Trang Thái", "Ixora"]'::jsonb, 'Trang đỏ thuộc nhóm cây ban công, cây sân vườn. Có 2 quy cách.', 'Trang đỏ có chùm hoa tròn màu đỏ rực, lá xanh bóng, ra hoa gần như quanh năm. Cây chịu nắng, dễ cắt tỉa, hợp chậu ban công, bồn viền, hàng rào.'),
('trang-vang', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 30–80cm"], ["Công dụng", "Chậu ban công, bồn viền, hàng rào thấp, cúng lễ"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Ixora (giống hoa vàng)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công nắng, sân vườn"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Sắc vàng tượng trưng cho tài lộc, may mắn", "placement": "Ban công, sân trước"}'::jsonb, '["Trang Thái", "Ixora"]'::jsonb, 'Trang vàng thuộc nhóm cây ban công, cây sân vườn. Có 2 quy cách.', 'Trang vàng có chùm hoa tròn màu vàng tươi, lá xanh bóng, ra hoa nhiều mùa nắng. Cây chịu nắng, dễ cắt tỉa, hợp chậu ban công, bồn viền.'),
('trau-ba-leo', '[["Ánh sáng", "Ánh sáng tán xạ, chịu bóng râm và đèn điện"], ["Tưới nước", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần/tuần; không để đọng nước dưới đáy chậu"], ["Đất trồng", "Đất tơi xốp thoát nước: đất sạch trộn xơ dừa, trấu hun, phân trùn quế"], ["Bón phân", "Phân tan chậm hoặc NPK 20-20-20 pha loãng, 1 lần/tháng"], ["Nhiệt độ, độ ẩm", "Thích hợp 18–32°C, ưa ẩm; tránh gió máy lạnh thổi thẳng vào cây"], ["Mức độ dễ chăm", "Rất dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây dài 1–3m khi leo cột hoặc rủ"], ["An toàn thú cưng", "Không — nhựa cây gây ngứa, độc nếu nhai phải (tinh thể canxi oxalat)"], ["Công dụng", "Leo cột, chậu treo, để kệ, thủy sinh"], ["Cách nhân giống", "Giâm ngọn vào nước hoặc đất, rất dễ ra rễ"], ["Nguồn gốc", "Quần đảo Society (Thái Bình Dương)"], ["Tên khoa học", "Epipremnum aureum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng nước, rệp sáp, nhện đỏ; lá vàng nếu thiếu sáng lâu ngày"], ["Phù hợp với ai", "Người mới trồng cây, căn hộ, văn phòng"]]'::jsonb, '{"mau": ["xanh", "loang"], "anhSang": ["sang", "ram", "den"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự phát triển, may mắn, tiền tài", "placement": "Kệ sách, bàn làm việc, góc phòng khách"}'::jsonb, '["Vạn niên thanh leo", "Pothos", "Hoàng tâm"]'::jsonb, 'Trầu bà leo thuộc nhóm cây ban công. Quy cách: Dây dài 50–100cm.', 'Trầu bà leo là cây trầu bà dây dài, lá hình tim xanh bóng, có thể cho leo cột, leo tường hoặc rủ từ ban công. Cây lớn nhanh, rất dễ chăm.'),
('do-la', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ"], ["Tưới nước", "Tưới khi giá thể se khô, 2–3 lần/tuần; lá dày trữ nước"], ["Đất trồng", "Giá thể thoáng: xơ dừa, vỏ thông, ít đất"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây rủ 50cm–1m"], ["Công dụng", "Chậu treo ban công, cửa sổ, hiên"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Dischidia"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Ban công, căn hộ"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["sang", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá tròn như đồng tiền tượng trưng cho tài lộc", "placement": "Ban công, cửa sổ, quầy hàng"}'::jsonb, '["Dây đô la", "Dischidia"]'::jsonb, 'Đô la thuộc nhóm cây ban công. Quy cách: Dây dài 50–100cm.', 'Đô la là cây dây rủ lá tròn nhỏ dày như những đồng xu xâu thành chuỗi. Cây hợp chậu treo ban công, cửa sổ, hiên nhà, ít sâu bệnh.'),
('thai-lai-tia', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; chịu hạn khá"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây bò, rủ 30–50cm"], ["An toàn thú cưng", "Không — nhựa gây kích ứng da với chó mèo"], ["Công dụng", "Chậu treo, bồn viền, phủ nền"], ["Cách nhân giống", "Giâm ngọn, rất dễ ra rễ"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Tradescantia pallida"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người mới trồng cây"]]'::jsonb, '{"mau": ["tim"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Sắc tím tượng trưng cho sự thủy chung, bình an", "placement": "Ban công, cửa sổ"}'::jsonb, '["Lẻ bạn tím", "Purple heart"]'::jsonb, 'Thài lài tía thuộc nhóm cây ban công. Quy cách: Dây dài 30–50cm.', 'Thài lài tía có lá thon dài màu tím đậm, thân bò rủ mềm, hoa nhỏ màu hồng. Cây lớn nhanh, rất dễ trồng, hợp chậu treo, bồn viền tạo mảng màu tím.'),
('thai-lai-xanh', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; chịu hạn khá"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây bò, rủ 30–50cm"], ["An toàn thú cưng", "Không — nhựa gây kích ứng da với chó mèo"], ["Công dụng", "Chậu treo, bồn viền, phủ nền"], ["Cách nhân giống", "Giâm ngọn, rất dễ ra rễ"], ["Nguồn gốc", "Mexico"], ["Tên khoa học", "Tradescantia"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Người mới trồng cây"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sức sống, sự phát triển", "placement": "Ban công, cửa sổ"}'::jsonb, '["Lẻ bạn tím", "Purple heart"]'::jsonb, 'Thài lài xanh thuộc nhóm cây ban công. Quy cách: Dây dài 30–50cm.', 'Thài lài xanh có lá xanh tươi, thân bò rủ mềm, lớn rất nhanh. Cây dễ trồng, hợp chậu treo, phủ nền bóng râm nhẹ.'),
('thu-hai-duong', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ buổi sáng; tránh nắng gắt"], ["Tưới nước", "Tưới khi mặt đất se khô; không tưới đẫm lên lá, hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Ưa mát 18–28°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 20–40cm"], ["An toàn thú cưng", "Không — độc với chó mèo (đặc biệt củ, rễ)"], ["Công dụng", "Chậu ban công, cửa sổ, chậu treo"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Vùng nhiệt đới, cận nhiệt đới"], ["Tên khoa học", "Begonia"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nắng sáng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-nhe", "sang"], "cham": "vua", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự đằm thắm, hạnh phúc", "placement": "Ban công, cửa sổ"}'::jsonb, '["Begonia"]'::jsonb, 'Thu hải đường thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Thu hải đường có hoa đỏ, hồng, trắng nở dày, lá dày bóng, nhiều giống lá có màu. Cây ưa nắng nhẹ, mát, hợp chậu ban công hướng Đông, cửa sổ.'),
('phong-lu-thao', '[["Ánh sáng", "Nắng trực tiếp 4–6 giờ/ngày để ra hoa nhiều"], ["Tưới nước", "Tưới khi đất se khô; kỵ úng"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Chiều cao", "25–40cm"], ["Nhiệt độ, độ ẩm", "Ưa mát 18–28°C"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 25–40cm"], ["An toàn thú cưng", "Không — độc với chó mèo"], ["Công dụng", "Chậu ban công, cửa sổ"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Nam Phi"], ["Tên khoa học", "Pelargonium × hortorum"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nắng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự ấm áp, niềm vui", "placement": "Ban công, cửa sổ"}'::jsonb, '["Phong lữ", "Thiên trúc quỳ", "Geranium"]'::jsonb, 'Phong lữ thảo thuộc nhóm cây ban công. Quy cách: Cao 25–40cm.', 'Phong lữ thảo có chùm hoa tròn đỏ, hồng, trắng vươn cao trên tán lá tròn thơm nhẹ, ra hoa nhiều mùa. Cây ưa nắng, khô thoáng, hợp chậu ban công, cửa sổ.'),
('thu-hai-duong-ru', '[["Ánh sáng", "Ánh sáng tán xạ đến nắng nhẹ buổi sáng; tránh nắng gắt"], ["Tưới nước", "Tưới khi mặt đất se khô; không tưới đẫm lên lá, hoa"], ["Đất trồng", "Đất tơi xốp giàu mùn, trộn phân chuồng hoai, thoát nước tốt"], ["Bón phân", "NPK giàu lân (10-30-10) 2 tuần/lần khi ra nụ; phân hữu cơ định kỳ"], ["Nhiệt độ, độ ẩm", "Ưa mát 18–28°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây rủ 30–50cm"], ["An toàn thú cưng", "Không — độc với chó mèo (đặc biệt củ, rễ)"], ["Công dụng", "Chậu ban công, cửa sổ, chậu treo"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Vùng nhiệt đới, cận nhiệt đới"], ["Tên khoa học", "Begonia"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá, nấm phấn trắng khi ẩm kéo dài"], ["Phù hợp với ai", "Ban công nắng sáng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-nhe", "sang"], "cham": "vua", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự đằm thắm, hạnh phúc", "placement": "Ban công, cửa sổ"}'::jsonb, '["Begonia"]'::jsonb, 'Thu hải đường rủ thuộc nhóm cây ban công. Quy cách: Dây dài 30–50cm.', 'Thu hải đường rủ có cành mềm rủ xuống phủ đầy hoa, rất hợp chậu treo ban công, cửa sổ. Cây ưa nắng nhẹ buổi sáng, khí hậu mát.'),
('hoa-lai', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 50cm–1,5m"], ["An toàn thú cưng", "An toàn với chó mèo (không độc)"], ["Công dụng", "Chậu ban công, sân vườn, ướp trà, cúng lễ"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Jasminum sambac"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người thích hoa thơm"]]'::jsonb, '{"mau": ["bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "an-toan"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng thơm tượng trưng cho sự thanh khiết, tình yêu trong sáng", "placement": "Ban công, cửa sổ phòng khách"}'::jsonb, '["Nhài", "Jasmine"]'::jsonb, 'Hoa lài thuộc nhóm cây ban công, cây sân vườn. Có 2 quy cách.', 'Hoa lài (nhài) có hoa trắng nhỏ thơm ngát, nở nhiều về chiều tối, thường dùng ướp trà. Cây ưa nắng, dễ trồng chậu ban công, sân vườn.'),
('hoa-nguyet-que', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 50cm–1m (chậu ban công)"], ["Công dụng", "Sân vườn, hàng rào, bonsai, trồng chậu lối vào"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á, Úc"], ["Tên khoa học", "Murraya paniculata"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, nhà phố có sân"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho vinh quang, chiến thắng, may mắn", "placement": "Sân trước, lối vào"}'::jsonb, '["Nguyệt quế", "Orange jasmine"]'::jsonb, 'Hoa nguyệt quế thuộc nhóm cây ban công. Quy cách: Cao 50–80cm.', 'Nguyệt quế trồng chậu ban công có tán lá xanh bóng, hoa trắng nhỏ thơm ngát nở nhiều đợt trong năm. Cây ưa nắng, dễ cắt tỉa tạo dáng.'),
('hoa-mai-van-phuc', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "40–60cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 50cm–1m"], ["Công dụng", "Chậu ban công, bồn hoa, hàng rào thấp"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Tabernaemontana divaricata (giống lùn)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công, sân vườn"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho phúc lộc, may mắn, thanh khiết", "placement": "Ban công, sân trước"}'::jsonb, '["Mai tiểu thư", "Mai chỉ thiên"]'::jsonb, 'Hoa mai vạn phúc thuộc nhóm cây ban công. Quy cách: Cao 40–60cm.', 'Mai vạn phúc có lá xanh bóng, hoa trắng 5 cánh xoắn chong chóng nở quanh năm, mùi thơm nhẹ. Cây ưa nắng, dễ trồng, hợp chậu ban công, bồn hoa, hàng rào thấp.'),
('hoa-huynh-anh', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng nhẹ; đủ nắng mới ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giảm khi trời mưa"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 2–5m"], ["An toàn thú cưng", "Không — nhựa độc với chó mèo"], ["Công dụng", "Leo giàn, cổng, hàng rào, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Brazil"], ["Tên khoa học", "Allamanda cathartica"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Nhà có giàn, sân vườn"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Sắc vàng tượng trưng cho tài lộc, sự rực rỡ", "placement": "Cổng, giàn sân trước"}'::jsonb, '["Dây huỳnh anh", "Golden trumpet"]'::jsonb, 'Hoa huỳnh anh thuộc nhóm cây ban công. Quy cách: Dây dài 80–120cm.', 'Huỳnh anh có hoa vàng tươi hình kèn, lá xanh bóng, ra hoa gần như quanh năm. Cây ưa nắng, lớn nhanh, hợp leo giàn, cổng, hàng rào.'),
('cay-khe', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–5m"], ["Công dụng", "Sân vườn, bóng mát, lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Averrhoa carambola"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân"]]'::jsonb, '{"mau": ["xanh", "tim"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Trái sai tượng trưng cho sung túc, đủ đầy", "placement": "Sân sau, sân vườn"}'::jsonb, '["Khế", "Star fruit"]'::jsonb, 'Cây khế thuộc nhóm cây sân vườn. Có 2 quy cách.', 'Khế là cây ăn trái quen thuộc, hoa tím hồng nhỏ, trái 5 múi hình ngôi sao chua ngọt. Cây cho bóng mát, trồng chậu sân vườn, sân thượng vẫn ra trái.'),
('san-ho', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "1–1,5m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m"], ["An toàn thú cưng", "Không — độc nếu ăn phải (hạt, nhựa)"], ["Công dụng", "Sân vườn, bồn cây"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Mexico, vùng Caribe"], ["Tên khoa học", "Jatropha multifida"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Sân vườn không có trẻ nhỏ"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Hoa đỏ rực tượng trưng cho may mắn", "placement": "Sân vườn"}'::jsonb, '["Bạch phụ tử", "Dầu mè đỏ", "Coral plant"]'::jsonb, 'San hô thuộc nhóm cây sân vườn. Quy cách: Cao 1–1,5m.', 'San hô có lá xẻ thùy sâu như chân vịt, cụm hoa đỏ tươi mọc trên đỉnh như nhánh san hô. Cây chịu nắng hạn, hợp trồng sân vườn, bồn cây. Mọi bộ phận có độc, không trồng nơi trẻ nhỏ hay nghịch.'),
('su-thai', '[["Ánh sáng", "Nắng trực tiếp nhiều giờ"], ["Tưới nước", "Tưới khi đất khô hẳn, khoảng 1 lần/tuần (mùa mưa thưa hơn); tránh đọng nước ở nách lá"], ["Đất trồng", "Giá thể thoát nước nhanh: sỏi nhỏ, đá perlite, trấu hun trộn ít đất"], ["Bón phân", "Phân tan chậm liều nhẹ, 1–2 tháng/lần"], ["Chiều cao", "60–100cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 15–35°C, ưa khô thoáng; mưa dầm dễ thối"], ["Mức độ dễ chăm", "Dễ chăm — chỉ cần đủ nắng, ít nước"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 30cm–1m, gốc phình to"], ["An toàn thú cưng", "Không — nhựa rất độc"], ["Công dụng", "Ban công nắng, sân thượng, bonsai"], ["Cách nhân giống", "Ghép, giâm cành, gieo hạt"], ["Nguồn gốc", "Đông Phi, bán đảo Ả Rập"], ["Tên khoa học", "Adenium obesum"], ["Sâu bệnh thường gặp", "Thối gốc khi úng, rệp sáp ở nách lá"], ["Phù hợp với ai", "Ban công, sân thượng nhiều nắng"]]'::jsonb, '{"mau": ["do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Tượng trưng cho sự sung túc, may mắn", "placement": "Ban công, sân trước"}'::jsonb, '["Sứ sa mạc", "Desert rose"]'::jsonb, 'Sứ Thái thuộc nhóm cây sân vườn. Quy cách: Cao 60–100cm.', 'Sứ Thái có gốc phình to như củ, dễ tạo dáng, hoa hồng đỏ rực nở nhiều đợt trong năm. Cây rất chịu nắng hạn, hợp ban công nắng, sân thượng, sân vườn.'),
('su-dai', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Tưới khi đất khô; cây chịu hạn tốt, kỵ úng"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 2–6m"], ["An toàn thú cưng", "Nhựa trắng gây kích ứng"], ["Công dụng", "Sân vườn, đình chùa, resort, công trình"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Mexico, Trung Mỹ"], ["Tên khoa học", "Plumeria rubra"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, resort, đình chùa"]]'::jsonb, '{"mau": ["bac-trang", "do-hong", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho sự thanh khiết, trường tồn", "placement": "Sân vườn, xa cửa chính"}'::jsonb, '["Hoa đại", "Hoa sứ cùi", "Frangipani"]'::jsonb, 'Sứ đại thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Sứ đại có thân cành mập, hoa trắng nhụy vàng hoặc hồng đỏ thơm ngát, nở nhiều mùa nắng. Cây chịu nắng hạn, sống lâu, hay trồng sân vườn, đình chùa, resort.'),
('nguyet-que', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m, tán tròn"], ["Công dụng", "Sân vườn, hàng rào, bonsai, trồng chậu lối vào"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á, Úc"], ["Tên khoa học", "Murraya paniculata"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, nhà phố có sân"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho vinh quang, chiến thắng, may mắn", "placement": "Sân trước, lối vào"}'::jsonb, '["Orange jasmine"]'::jsonb, 'Nguyệt quế thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Nguyệt quế có tán lá xanh đậm bóng, hoa trắng nhỏ thơm ngát nở nhiều đợt và quả đỏ cam. Cây dễ uốn tạo dáng, hợp trồng chậu sân vườn, hàng rào, bonsai.'),
('mai-vang', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón kali, lân trước Tết để hoa nở đúng dịp"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Chưng Tết, sân vườn, cây dáng thế"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Nam Á (có ở Việt Nam)"], ["Tên khoa học", "Ochna integerrima"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Gia đình miền Nam, người chơi cây cảnh"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Tượng trưng cho phú quý, may mắn, khởi đầu thuận lợi trong năm mới", "placement": "Phòng khách dịp Tết, sân trước"}'::jsonb, '["Hoàng mai", "Mai"]'::jsonb, 'Mai vàng thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Mai vàng là biểu tượng ngày Tết phương Nam, hoa vàng 5 cánh nở rộ vào dịp xuân. Cây cần nắng, tuốt lá và điều chỉnh nước, phân để hoa nở đúng Tết.'),
('mai-chieu-thuy', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Chậm đến trung bình"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["Công dụng", "Bonsai, tiểu cảnh, sân vườn"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Wrightia religiosa"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người chơi bonsai"]]'::jsonb, '{"mau": ["bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho sự thanh cao, may mắn", "placement": "Sân trước, ban công rộng"}'::jsonb, '["Mai chấn thủy", "Mai trúc thủy"]'::jsonb, 'Mai chiếu thủy thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Mai chiếu thủy có lá nhỏ, hoa trắng li ti rủ xuống, thơm dịu, đặc biệt về đêm. Cây dễ uốn tạo dáng bonsai, ưa nắng, hợp chậu sân vườn, tiểu cảnh.'),
('tung-coi', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Chậm"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Sân vườn, cổng, bonsai"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Á"], ["Tên khoa học", "Juniperus chinensis"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, người chơi cây cảnh"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự trường thọ, bền bỉ", "placement": "Sân trước, cổng"}'::jsonb, '["Chinese juniper"]'::jsonb, 'Tùng cối thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Tùng cối có lá kim ngắn xếp dày, thân gỗ xoắn, dáng bề thế cổ kính. Cây ưa nắng, chịu hạn khá, thường trồng chậu sân vườn, cổng hoặc làm bonsai.'),
('cay-sanh', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 1–3m (dáng thế)"], ["An toàn thú cưng", "Không — nhựa trắng gây kích ứng"], ["Công dụng", "Cây dáng thế sân vườn, bonsai, tiểu cảnh"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Châu Á nhiệt đới"], ["Tên khoa học", "Ficus (họ Dâu tằm)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người chơi cây cảnh, biệt thự"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sức sống bền bỉ, sung túc", "placement": "Sân trước, cạnh hồ nước"}'::jsonb, '["Sanh"]'::jsonb, 'Cây sanh thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Sanh là cây dáng thế quen thuộc của người chơi cây cảnh Việt, thân gỗ nhiều u nần, rễ khí, tán lá nhỏ dày. Cây khỏe, chịu cắt tỉa, sống lâu năm.'),
('cay-si', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng sáng; cây dáng thế để ngoài trời"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 1–3m (dáng thế)"], ["An toàn thú cưng", "Không — nhựa trắng gây kích ứng"], ["Công dụng", "Cây dáng thế sân vườn, bonsai, tiểu cảnh"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Châu Á nhiệt đới"], ["Tên khoa học", "Ficus benjamina"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Người chơi cây cảnh, biệt thự"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sức sống bền bỉ, sung túc", "placement": "Sân trước, cạnh hồ nước"}'::jsonb, '["Si", "Weeping fig"]'::jsonb, 'Cây si thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Si có tán lá nhỏ xanh bóng, rễ khí buông dài, thân gỗ dễ tạo dáng. Cây khỏe, lớn nhanh, trồng làm cây dáng thế, bonsai hoặc cây bóng mát.'),
('da-bup-do', '[["Ánh sáng", "Nắng nhẹ đến sáng tán xạ; trồng ngoài trời chịu nắng tốt"], ["Tưới nước", "Tưới 1–2 lần/ngày mùa nắng, giữ đất ẩm nhưng không úng"], ["Đất trồng", "Đất thịt trộn xơ dừa, phân hữu cơ hoai, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 1–2 tháng/lần; bón nhẹ để giữ dáng"], ["Chiều cao", "1–1,5m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt"], ["Mức độ dễ chăm", "Trung bình — cần cắt tỉa giữ dáng"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 1–3m trong chậu"], ["An toàn thú cưng", "Không — nhựa trắng gây kích ứng, độc nhẹ"], ["Công dụng", "Phòng khách sáng, sảnh, sân vườn"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Bắc Ấn Độ, Đông Nam Á"], ["Tên khoa học", "Ficus elastica"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Gia đình, văn phòng, biệt thự"]]'::jsonb, '{"mau": ["xanh-dam", "do-hong"], "anhSang": ["nang-nhe", "sang", "nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự vững chãi, sung túc", "placement": "Phòng khách sáng, sảnh, sân"}'::jsonb, '["Đa cao su", "Rubber plant"]'::jsonb, 'Đa búp đỏ thuộc nhóm cây sân vườn. Quy cách: Cao 1–1,5m.', 'Đa búp đỏ có lá to dày bóng xanh đậm, búp non bọc vỏ đỏ nổi bật. Cây khỏe, lớn nhanh, trồng chậu trong nhà sáng hoặc sân vườn đều được.'),
('bang-dai-loan', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 5–15m, tán tầng"], ["Công dụng", "Bóng mát sân vườn, đường nội bộ, công viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Madagascar"], ["Tên khoa học", "Terminalia mantaly"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, khu đô thị, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tán tầng tượng trưng cho sự thăng tiến, sung túc", "placement": "Sân vườn, lối vào"}'::jsonb, '["Bàng lá nhỏ", "Madagascar almond"]'::jsonb, 'Bàng Đài Loan thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Bàng Đài Loan có tán xếp tầng đều đặn như những chiếc đĩa, lá nhỏ xanh mướt. Cây chịu nắng gió, ít rụng lá, hợp trồng sân vườn, đường nội bộ, công viên.'),
('truc-quan-tu', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 2–4m, mọc thành bụi"], ["Công dụng", "Hàng rào, che chắn, tiểu cảnh"], ["Cách nhân giống", "Tách bụi"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, quán cà phê, resort"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho người quân tử ngay thẳng, thanh cao", "placement": "Sân vườn, hàng rào"}'::jsonb, '[]'::jsonb, 'Trúc quân tử thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Trúc quân tử mọc thành bụi, thân thẳng chia đốt, lá thon nhỏ, tạo vẻ thanh tao. Cây trồng làm hàng rào, che chắn, tiểu cảnh sân vườn, quán cà phê.'),
('truc-can-cau', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 2–5m"], ["Công dụng", "Hàng rào, che chắn, tiểu cảnh"], ["Cách nhân giống", "Tách bụi, giâm thân ngầm"], ["Nguồn gốc", "Trung Quốc"], ["Tên khoa học", "Phyllostachys aurea"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, quán cà phê, resort"]]'::jsonb, '{"mau": ["xanh", "vang"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự ngay thẳng, kiên cường", "placement": "Sân vườn, hàng rào"}'::jsonb, '["Trúc vàng", "Golden bamboo"]'::jsonb, 'Trúc cần câu thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Trúc cần câu có thân thẳng mảnh, đốt gần nhau phía gốc, lá nhỏ xanh, mọc thành bụi dày. Cây trồng hàng rào, che chắn, tiểu cảnh kiểu Nhật.'),
('cay-coc', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "1–1,5m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–5m (trồng chậu thấp hơn)"], ["Công dụng", "Sân vườn, trồng chậu lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Polynesia, Đông Nam Á"], ["Tên khoa học", "Spondias dulcis"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân, sân thượng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Cây trái sai quả tượng trưng cho sung túc", "placement": "Sân sau, sân vườn"}'::jsonb, '["Cóc", "Ambarella"]'::jsonb, 'Cây cóc thuộc nhóm cây sân vườn. Quy cách: Cao 1–1,5m.', 'Cóc là cây ăn trái lá kép, trái xanh giòn vị chua ngọt, rất quen thuộc ở miền Nam. Cây trồng chậu sân vườn vẫn cho trái, chịu nắng tốt.'),
('cay-oi', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "1–1,5m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–4m"], ["Công dụng", "Sân vườn, sân thượng, lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Trung Mỹ, Nam Mỹ"], ["Tên khoa học", "Psidium guajava"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân, sân thượng"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Cây trái sai quả tượng trưng cho sung túc", "placement": "Sân sau, sân vườn"}'::jsonb, '["Ổi", "Guava"]'::jsonb, 'Cây ổi thuộc nhóm cây sân vườn. Quy cách: Cao 1–1,5m.', 'Ổi là cây ăn trái dễ trồng, cho trái quanh năm, trái giòn ngọt giàu vitamin C. Cây chịu nắng, trồng chậu sân thượng, sân vườn vẫn ra trái.'),
('cay-xoai', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "1,5–2m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 3–10m (trồng chậu 1,5–3m)"], ["Công dụng", "Bóng mát, lấy trái, sân vườn"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Nam Á"], ["Tên khoa học", "Mangifera indica"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân rộng"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Cây trái sai quả tượng trưng cho sung túc, đủ đầy", "placement": "Sân sau, sân vườn"}'::jsonb, '["Xoài", "Mango"]'::jsonb, 'Cây xoài thuộc nhóm cây sân vườn. Quy cách: Cao 1,5–2m.', 'Xoài là cây ăn trái tán rộng, lá non đỏ tía, trái thơm ngọt. Cây vừa cho bóng mát vừa cho trái, hợp sân vườn rộng; trồng chậu lớn cần cắt tỉa giữ tán.'),
