('cay-tac', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 80cm–2m"], ["An toàn thú cưng", "Không — độc nhẹ với chó mèo (tinh dầu)"], ["Công dụng", "Chưng Tết, sân vườn, ban công, lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Citrus × microcarpa"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Gia đình, người chơi cây Tết"]]'::jsonb, '{"mau": ["xanh-dam", "vang"], "anhSang": ["nang-gat"], "cham": "vua", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Trái vàng sai quả tượng trưng cho tài lộc, sung túc", "placement": "Phòng khách dịp Tết, sân trước"}'::jsonb, '["Tắc", "Quất", "Calamansi"]'::jsonb, 'Cây tắc thuộc nhóm cây sân vườn. Quy cách: Cao 80–120cm.', 'Tắc (quất) là cây ăn trái nhỏ, trái tròn vàng cam chua thơm, sai quả. Cây trồng chậu đẹp, thường chưng Tết, vừa làm cảnh vừa lấy trái.'),
('cay-me', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "1,5–2m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 5–15m (trồng chậu 1,5–2m)"], ["Công dụng", "Bóng mát, lấy trái, bonsai"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Châu Phi nhiệt đới"], ["Tên khoa học", "Tamarindus indica"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân rộng, công trình"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự bền bỉ, sung túc", "placement": "Sân vườn"}'::jsonb, '["Me", "Tamarind"]'::jsonb, 'Cây me thuộc nhóm cây sân vườn. Quy cách: Cao 1,5–2m.', 'Me là cây gỗ lá kép nhỏ li ti, trái dài chua dùng nấu canh, làm mứt. Cây chịu nắng hạn, sống lâu, cho bóng mát, cũng hay được tạo dáng bonsai.'),
('cay-man', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "1–1,5m"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 2–5m"], ["Công dụng", "Sân vườn, lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Syzygium samarangense"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân"]]'::jsonb, '{"mau": ["xanh-dam", "do-hong"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Trái đỏ sai quả tượng trưng cho may mắn, sung túc", "placement": "Sân sau, sân vườn"}'::jsonb, '["Mận", "Roi", "Wax apple"]'::jsonb, 'Cây mận thuộc nhóm cây sân vườn. Quy cách: Cao 1–1,5m.', 'Mận (roi) là cây ăn trái miền Nam, trái hình chuông đỏ hồng giòn mát. Cây cho bóng mát, trồng chậu lớn sân vườn vẫn ra trái.'),
('cay-so-ri', '[["Ánh sáng", "Nắng toàn phần, ít nhất 6 giờ/ngày"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; giữ ẩm đều khi ra hoa, nuôi trái"], ["Đất trồng", "Đất thịt giàu mùn, thoát nước tốt; trồng chậu cần chậu lớn có lỗ thoát"], ["Bón phân", "Phân chuồng hoai + NPK định kỳ 1–2 tháng/lần; tăng kali khi nuôi trái"], ["Chiều cao", "80–120cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 22–35°C"], ["Mức độ dễ chăm", "Trung bình"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Sân vườn, sân thượng, lấy trái"], ["Cách nhân giống", "Chiết cành, ghép, gieo hạt"], ["Nguồn gốc", "Vùng Caribe, Trung Mỹ"], ["Tên khoa học", "Malpighia emarginata"], ["Sâu bệnh thường gặp", "Rệp, sâu đục trái, ruồi vàng, nấm bệnh trên lá"], ["Phù hợp với ai", "Nhà có sân, sân thượng"]]'::jsonb, '{"mau": ["xanh", "do-hong"], "anhSang": ["nang-gat"], "cham": "vua"}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Trái đỏ tượng trưng cho may mắn", "placement": "Sân sau, sân thượng"}'::jsonb, '["Sơ ri", "Acerola"]'::jsonb, 'Cây sơ ri thuộc nhóm cây sân vườn. Quy cách: Cao 80–120cm.', 'Sơ ri là cây bụi ăn trái, trái đỏ mọng giàu vitamin C, ra nhiều đợt trong năm. Cây dễ trồng chậu, chịu nắng, hợp sân thượng, sân vườn.'),
('cay-hong-loc', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "60–100cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Hàng rào, cây tạo hình, viền lối đi"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Syzygium oleinum"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình cảnh quan"]]'::jsonb, '{"mau": ["do-hong", "xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Lá non đỏ tượng trưng cho lộc mới, may mắn", "placement": "Hàng rào, sân trước"}'::jsonb, '["Hồng lộc"]'::jsonb, 'Cây hồng lộc thuộc nhóm cây sân vườn. Quy cách: Cao 60–100cm.', 'Hồng lộc có lá non đỏ hồng rực rỡ, chuyển xanh khi già, tán dày dễ cắt tỉa. Cây trồng hàng rào, cây tạo hình tròn, viền lối đi, rất được ưa chuộng.'),
('mai-van-phuc', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "50–80cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 50cm–1m"], ["Công dụng", "Chậu ban công, bồn hoa, hàng rào thấp"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Tabernaemontana divaricata (giống lùn)"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Ban công, sân vườn"]]'::jsonb, '{"mau": ["xanh-dam", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Tượng trưng cho phúc lộc, may mắn, thanh khiết", "placement": "Ban công, sân trước"}'::jsonb, '["Mai tiểu thư", "Mai chỉ thiên"]'::jsonb, 'Mai vạn phúc thuộc nhóm cây sân vườn. Quy cách: Cao 50–80cm.', 'Mai vạn phúc có lá xanh bóng, hoa trắng 5 cánh xoắn chong chóng nở quanh năm, mùi thơm nhẹ. Cây ưa nắng, dễ trồng, hợp chậu ban công, bồn hoa, hàng rào thấp.'),
('huynh-anh', '[["Ánh sáng", "Nắng trực tiếp hoặc nắng nhẹ; đủ nắng mới ra hoa nhiều"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, giảm khi trời mưa"], ["Đất trồng", "Đất giàu mùn, tơi xốp, thoát nước tốt"], ["Bón phân", "Phân hữu cơ hoai 2 tháng/lần, NPK giàu lân khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C"], ["Mức độ dễ chăm", "Dễ chăm — cần giàn hoặc lưới cho cây leo"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Dây leo dài 2–5m"], ["An toàn thú cưng", "Không — nhựa độc với chó mèo"], ["Công dụng", "Leo giàn, cổng, hàng rào, ban công"], ["Cách nhân giống", "Giâm cành, gieo hạt"], ["Nguồn gốc", "Brazil"], ["Tên khoa học", "Allamanda cathartica"], ["Sâu bệnh thường gặp", "Rệp, sâu ăn lá"], ["Phù hợp với ai", "Nhà có giàn, sân vườn"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Sắc vàng tượng trưng cho tài lộc, sự rực rỡ", "placement": "Cổng, giàn sân trước"}'::jsonb, '["Dây huỳnh anh", "Golden trumpet"]'::jsonb, 'Huỳnh anh thuộc nhóm cây sân vườn. Quy cách: Dây dài 1–2m.', 'Huỳnh anh có hoa vàng tươi hình kèn, lá xanh bóng, ra hoa gần như quanh năm. Cây ưa nắng, lớn nhanh, hợp leo giàn, cổng, hàng rào.'),
('chuoi-canh', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp"], ["Tưới nước", "Giữ đất ẩm, tưới 1 lần/ngày mùa nắng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–2m"], ["Công dụng", "Sân vườn nhiệt đới, resort, hồ bơi"], ["Cách nhân giống", "Tách bụi"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, resort"]]'::jsonb, '{"mau": ["xanh", "co-hoa"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Lá to xanh tượng trưng cho sự sung túc", "placement": "Sân vườn"}'::jsonb, '[]'::jsonb, 'Chuối cảnh thuộc nhóm cây sân vườn, cây công trình. Có 2 quy cách.', 'Chuối cảnh là nhóm cây lá to dáng chuối, nhiều giống có hoa hoặc lá màu nổi bật, mang phong cách nhiệt đới. Cây hợp trồng sân vườn, resort, hồ bơi.'),
('co-dau', '[["Ánh sáng", "Nắng trực tiếp"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 5–20m"], ["Công dụng", "Cảnh quan khuôn viên, resort, đường nội bộ"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Nguồn gốc", "Tây Phi"], ["Tên khoa học", "Elaeis guineensis"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Công trình, resort"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự sung túc", "placement": "Khuôn viên"}'::jsonb, '["Oil palm"]'::jsonb, 'Cọ dầu thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Cọ dầu có thân to, tán lá kép dài xòe rộng, dáng nhiệt đới bề thế. Cây chịu nắng, trồng làm cảnh quan khuôn viên, resort, đường nội bộ.'),
('hoang-nam', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 8–15m, dáng tháp hẹp"], ["Công dụng", "Hàng cây lối đi, hàng rào cao, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Ấn Độ, Sri Lanka"], ["Tên khoa học", "Polyalthia longifolia"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Dáng thẳng tượng trưng cho sự vươn lên, ngay thẳng", "placement": "Dọc lối vào, hàng rào"}'::jsonb, '["Huyền diệp", "Mast tree"]'::jsonb, 'Hoàng nam thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Hoàng nam có dáng tháp hẹp cao vút, lá dài mép gợn sóng rủ xuống xanh đậm bóng. Cây chiếm ít diện tích, trồng thành hàng dọc lối đi, hàng rào cao, khuôn viên.'),
