('osaka-vang', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 5–10m"], ["Công dụng", "Cây đường phố, công viên, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Hoa vàng tượng trưng cho may mắn, thịnh vượng, bình yên", "placement": "Đường, công viên"}'::jsonb, '[]'::jsonb, 'Osaka vàng thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Osaka vàng là cây hoa thân gỗ, tán rộng, ra chùm hoa vàng rực. Cây lớn nhanh, rễ bám chắc, được trồng làm cây cảnh quan, cây đường phố.'),
('muong-hoang-yen', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 10–15m"], ["Công dụng", "Cây đường phố, công viên, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Nam Á"], ["Tên khoa học", "Cassia fistula"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Hoa vàng tượng trưng cho tài lộc, thịnh vượng", "placement": "Đường, công viên"}'::jsonb, '["Bò cạp vàng", "Hoàng yến", "Golden shower"]'::jsonb, 'Muồng hoàng yến thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Muồng hoàng yến có chùm hoa vàng tươi dài rủ xuống phủ kín tán vào mùa khô, rất rực rỡ. Cây trồng làm cây đường phố, công viên, khuôn viên.'),
('phuong-vang', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Nhanh"], ["Kích thước trưởng thành", "Cao 10–15m"], ["Công dụng", "Cây đường phố, công viên, khuôn viên"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đông Nam Á, Bắc Úc"], ["Tên khoa học", "Peltophorum pterocarpum"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, đô thị"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Hoa vàng tượng trưng cho tài lộc, thịnh vượng", "placement": "Đường, công viên"}'::jsonb, '["Lim xẹt", "Yellow flame tree"]'::jsonb, 'Phượng vàng thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Phượng vàng (lim xẹt) có tán rộng, lá kép nhỏ, hoa vàng tươi thành chùm lớn trên ngọn. Cây lớn nhanh, chịu nắng, trồng làm cây đường phố, công viên.'),
('chuong-vang', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 5–8m"], ["Công dụng", "Cây đường phố, công viên, sân vườn"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Nam Mỹ"], ["Tên khoa học", "Tabebuia argentea"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Công trình, biệt thự"]]'::jsonb, '{"mau": ["vang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "tho"], "ages": "", "meaning": "Hoa vàng tượng trưng cho tài lộc, may mắn", "placement": "Đường, sân vườn"}'::jsonb, '["Hoàng linh", "Silver trumpet tree"]'::jsonb, 'Chuông vàng thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Chuông vàng có thân vỏ xám bạc, hoa vàng rực hình chuông nở rộ khi cây gần trụi lá vào mùa khô. Cây trồng cây đường phố, công viên, sân vườn.'),
('ngoc-lan', '[["Ánh sáng", "Nắng toàn phần"], ["Tưới nước", "Mới trồng tưới 1 lần/ngày trong 1–2 tháng; cây đã bén rễ chỉ cần tưới mùa khô"], ["Đất trồng", "Hố trồng rộng gấp 2–3 lần bầu, trộn phân chuồng hoai; đất thoát nước"], ["Bón phân", "Phân chuồng hoai + NPK 2–3 lần/năm giai đoạn đầu"], ["Chiều cao", "2–4m"], ["Nhiệt độ, độ ẩm", "Chịu nóng tốt, phù hợp khí hậu miền Nam"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 5–15m"], ["Công dụng", "Sân vườn, khuôn viên, đình chùa"], ["Cách nhân giống", "Gieo hạt, giâm hoặc chiết cành"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Magnolia × alba (syn. Michelia × alba)"], ["Sâu bệnh thường gặp", "Sâu ăn lá, mối gốc, nấm bệnh mùa mưa"], ["Phù hợp với ai", "Biệt thự, đình chùa"]]'::jsonb, '{"mau": ["xanh", "bac-trang", "co-hoa"], "anhSang": ["nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["kim", "thuy"], "ages": "", "meaning": "Hoa trắng thơm tượng trưng cho sự thanh cao, tinh khiết", "placement": "Sân vườn"}'::jsonb, '["Ngọc lan trắng", "Bạch ngọc lan"]'::jsonb, 'Ngọc lan thuộc nhóm cây công trình. Quy cách: Cao 2–4m.', 'Ngọc lan có hoa trắng ngà cánh dài, hương thơm ngát lan xa, lá xanh bóng. Cây trồng sân vườn, khuôn viên, đình chùa, vừa bóng mát vừa có hoa thơm.'),
('co-canh', '[["Ánh sáng", "Nắng nhẹ đến nắng trực tiếp"], ["Tưới nước", "Tưới khi mặt đất se khô, 2–3 lần/tuần; mùa nắng tưới nhiều hơn"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Chiều cao", "1,5–3m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình"], ["Kích thước trưởng thành", "Cao 1,5–3m"], ["Công dụng", "Sân vườn, công trình, sảnh ngoài trời"], ["Cách nhân giống", "Gieo hạt, tách bụi"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Biệt thự, công trình cảnh quan"]]'::jsonb, '{"mau": ["xanh"], "anhSang": ["nang-nhe", "nang-gat"], "cham": "de"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tượng trưng cho sự che chở, bình an", "placement": "Sân vườn, lối vào"}'::jsonb, '[]'::jsonb, 'Cọ cảnh thuộc nhóm cây công trình. Quy cách: Cao 1,5–3m.', 'Cọ cảnh là các loài cọ lá quạt trồng làm cảnh, dáng gọn, chịu nắng tốt. Cây hợp trồng sân vườn, công trình, sảnh ngoài trời.'),
('thien-tue', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ"], ["Tưới nước", "Tưới khi đất khô, 2–3 lần/tuần; chịu hạn, kỵ úng"], ["Đất trồng", "Đất thịt tơi xốp trộn xơ dừa, phân hữu cơ hoai"], ["Bón phân", "Phân tan chậm hoặc NPK có vi lượng (magie) 1–2 tháng/lần"], ["Chiều cao", "1–2m"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–33°C, ưa ẩm"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Rất chậm"], ["Kích thước trưởng thành", "Cao 50cm–2m"], ["An toàn thú cưng", "Không — rất độc với chó mèo (đặc biệt hạt)"], ["Công dụng", "Cổng, sân vườn, công trình, đình chùa"], ["Cách nhân giống", "Tách chồi gốc, gieo hạt"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Cycas pectinata"], ["Sâu bệnh thường gặp", "Rệp sáp, nhện đỏ khi khô nóng; cháy chóp lá khi thiếu nước hoặc thiếu ẩm"], ["Phù hợp với ai", "Biệt thự, công trình, đình chùa"]]'::jsonb, '{"mau": ["xanh-dam"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên \"vạn tuế\" tượng trưng cho sự trường thọ, vững bền", "placement": "Hai bên cổng, sân trước"}'::jsonb, '[]'::jsonb, 'Thiên tuế thuộc nhóm cây công trình. Quy cách: Cao 1–2m.', 'Thiên tuế có thân trụ, lá kép dài xòe tròn ở ngọn, dáng cổ kính, lớn rất chậm. Cây chịu nắng hạn, hợp trồng sân vườn, công trình, đình chùa.'),
('dai-tuong-quan', '[["Ánh sáng", "Nắng trực tiếp đến bóng bán phần"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng; chịu ẩm tốt"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "80–150cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 80cm–1,5m"], ["An toàn thú cưng", "Không — củ độc với chó mèo"], ["Công dụng", "Bồn cây, viền lối đi, công trình"], ["Cách nhân giống", "Tách củ con"], ["Nguồn gốc", "Nam Á, Đông Nam Á"], ["Tên khoa học", "Crinum asiaticum"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Công trình cảnh quan, sân vườn"]]'::jsonb, '{"mau": ["xanh", "bac-trang", "co-hoa"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "thuCung": "doc"}'::jsonb, '{"elements": ["moc", "hoa"], "ages": "", "meaning": "Tên gọi tượng trưng cho uy quyền, sự bảo vệ", "placement": "Bồn cây sân trước"}'::jsonb, '["Náng hoa trắng", "Giant crinum lily"]'::jsonb, 'Đại tướng quân thuộc nhóm cây công trình. Quy cách: Cao 80–150cm.', 'Đại tướng quân có lá dài to xanh mướt mọc thành khóm từ củ, hoa trắng cánh mảnh thơm về đêm. Cây chịu nắng, ít sâu bệnh, trồng bồn, viền lối đi, công trình.'),
('hong-loc', '[["Ánh sáng", "Nắng trực tiếp đến nắng nhẹ; đủ nắng ra hoa, lá đẹp"], ["Tưới nước", "Tưới 1 lần/ngày mùa nắng, 2–3 lần/tuần mùa mưa; không để úng"], ["Đất trồng", "Đất thịt pha cát, giàu mùn, thoát nước tốt"], ["Bón phân", "Phân chuồng hoai 2–3 tháng/lần, bổ sung NPK khi ra hoa"], ["Chiều cao", "80–150cm"], ["Nhiệt độ, độ ẩm", "Thích hợp 20–35°C, chịu nóng tốt"], ["Mức độ dễ chăm", "Dễ chăm"], ["Tốc độ sinh trưởng", "Trung bình đến nhanh"], ["Kích thước trưởng thành", "Cao 1–3m"], ["Công dụng", "Hàng rào, cây tạo hình, viền lối đi"], ["Cách nhân giống", "Giâm cành, chiết cành"], ["Nguồn gốc", "Đông Nam Á"], ["Tên khoa học", "Syzygium oleinum"], ["Sâu bệnh thường gặp", "Rệp sáp, sâu ăn lá, nấm lá mùa mưa"], ["Phù hợp với ai", "Biệt thự, công trình cảnh quan"]]'::jsonb, '{"mau": ["do-hong", "xanh"], "anhSang": ["nang-gat", "nang-nhe"], "cham": "de", "chiuGio": true}'::jsonb, '{"elements": ["hoa", "tho"], "ages": "", "meaning": "Lá non đỏ tượng trưng cho lộc mới, may mắn", "placement": "Hàng rào, sân trước"}'::jsonb, '[]'::jsonb, 'Hồng lộc thuộc nhóm cây công trình. Quy cách: Cao 80–150cm.', 'Hồng lộc có lá non đỏ hồng rực rỡ, chuyển xanh khi già, tán dày dễ cắt tỉa. Cây trồng hàng rào, cây tạo hình tròn, viền lối đi, rất được ưa chuộng.');--> statement-breakpoint
